hpe11AddSection("hpe11-u01",{"id": "hpe11-s009-osteo-3", "title": "Balanced diet and suitable exercise (walking)", "headingUrdu": "متوازن غذا اور مناسب ورزش (چہل قدمی)", "headingPashto": "متوازن غذا او مناسب تمرین (ګرځېدل)", "sourceLanguage": "ur", "source": {"pdfPage": 9, "printedPage": "5"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s009-h1", "hpe11-s009-p2", "hpe11-s009-p3", "hpe11-s009-p4", "hpe11-s009-p5", "hpe11-s009-p6", "hpe11-s009-p7", "hpe11-s009-h8", "hpe11-s009-p9", "hpe11-s009-p10"]}], "equations": [], "sourceNote": "Printed page 5: balanced diet (five items) and suitable exercise with walking items i–ii; continues on page 6. English and Pashto are our translations (need native review); watermark and footer strip excluded; photographs not reproduced.", "review": {"reviewedAtUtc": "2026-10-13T02:23:17.042359+00:00", "scope": "Scan 9 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("1۔ متوازن غذا:","1. Balanced Diet:","۱. متوازن غذا:",{"id": "hpe11-s009-h1", "kind": "heading"}),
hpe11Pair("وہ غذا جس میں تمام غذائی اجزاء مناسب اور موزوں مقدار میں پائے جائیں متوازن غذا کہلاتی ہے۔ اپنی روز مرہ کی خوراک میں ضروری غذائی معدنیات اور پروٹین کا شامل کرنا اس مرض سے بچاؤ میں معاون ثابت ہوتا ہے۔ اس لیے خوراک میں درج ذیل چیزوں کو اہمیت دی جائے۔","Food in which all nutrients are found in suitable and proper quantity is called a balanced diet. Including necessary dietary minerals and protein in one’s daily food proves helpful in preventing this disease. Therefore the following things should be given importance in food.","هغه غذا چې په کې ټول غذايي اجزا په مناسبه او مناسبه اندازه موندل شي متوازن غذا بلل کېږي. د ورځني خوراک کې اړین غذايي معدنیات او پروټین شاملول له دې ناروغۍ د ژغورنې کې مرسته‌کوونکي ثابتېږي. له دې امله په خوراک کې لاندې شیانو ته اهمیت ورکړل شي.",{"id": "hpe11-s009-p2"}),
hpe11Pair("1۔ دودھ اور اس سے بنی اشیاء مثلاً دہی، مکھن، پنیر وغیرہ کا روزانہ مناسب استعمال۔","1. Daily suitable use of milk and things made from it, such as yoghurt, butter, cheese, etc.","۱. د شیدو او له هغو جوړو شویو شیانو لکه کنډیو، کوچو، پنیر او نور هره ورځ مناسب کارول.",{"id": "hpe11-s009-p3", "listGroup": "dt"}),
hpe11Pair("2۔ وٹامن ڈی پر مشتمل غذائی اجناس کا استعمال۔","2. Use of foodstuffs containing vitamin D.","۲. هغو غذايي توکو کارول چې وټامن ډي لري.",{"id": "hpe11-s009-p4", "listGroup": "dt"}),
hpe11Pair("3۔ مناسب مقدار میں مچھلی کا استعمال۔","3. Use of fish in suitable quantity.","۳. په مناسبه اندازه کب کارول.",{"id": "hpe11-s009-p5", "listGroup": "dt"}),
hpe11Pair("4۔ سبزیوں اور گوشت کا استعمال۔","4. Use of vegetables and meat.","۴. سبزیجاتو او غوښې کارول.",{"id": "hpe11-s009-p6", "listGroup": "dt"}),
hpe11Pair("5۔ موسمی پھلوں کا استعمال۔","5. Use of seasonal fruits.","۵. موسمي میوو کارول.",{"id": "hpe11-s009-p7", "listGroup": "dt"}),
hpe11Pair("2۔ مناسب ورزش:","2. Suitable Exercise:","۲. مناسب تمرین:",{"id": "hpe11-s009-h8", "kind": "heading"}),
hpe11Pair("ورزش اور سرگرمیوں سے جسم کو مضبوط اور لچکدار بنا کر اسے بیماریوں سے محفوظ رکھا جا سکتا ہے۔ درج ذیل جسمانی سرگرمیاں جسم کو لچکدار اور مضبوط بنا کر اس مرض سے محفوظ رکھنے میں اہم کردار ادا کرتی ہیں۔","By exercise and activities the body can be made strong and flexible and kept safe from diseases. The following physical activities play an important role in making the body flexible and strong and keeping it safe from this disease.","په تمرین او فعالیتونو سره بدن پیاوړی او نرم جوړولو سره له ناروغیو خوندي ساتل کېدای شي. لاندې فزیکي فعالیتونه بدن نرم او پیاوړی جوړولو سره له دې ناروغۍ د ساتلو کې مهم رول لوبوي.",{"id": "hpe11-s009-p9", "sourceGap": {"note": "A cartoon picture of a boy lifting a dumbbell is not reproduced."}}),
hpe11Pair("چہل قدمی: i۔ چہل قدمی نہایت آسان اور مفید ورزش ہے۔ پیدل چلنے کی عادت جسم کو فعال اور چست بناتی ہے۔ دوڑنا بھی مفید ہے لیکن معمر افراد کو اس سے پرہیز کرنا چاہیے۔ ii۔ سیڑھیاں چڑھنا، پہاڑ یا ڈھلوان کو سر کرنا بھی مفید سرگرمی ہے۔","Walking: i. Walking is a very easy and beneficial exercise. The habit of walking on foot makes the body active and agile. Running is also beneficial but elderly people should avoid it. ii. Climbing stairs and scaling a mountain or slope is also a beneficial activity.","ګرځېدل: i. ګرځېدل ډېر اسانه او ګټور تمرین دی. په پښو تګ عادت بدن فعال او چټک کوي. منډې وهل هم ګټور دي خو زاړه کسان باید ترې ډډه وکړي. ii. زینې خېژېدل، غره یا ځوړ ته خېژېدل هم ګټور فعالیت دی.",{"id": "hpe11-s009-p10", "listGroup": "wk"})
]});
