hpe11AddSection("hpe11-u01",{"id": "hpe11-s011-heart-1", "title": "Heart diseases: introduction and list", "headingUrdu": "دل کی بیماریاں، علامات اور وجوہات", "headingPashto": "د زړه ناروغۍ، نښې او لاملونه", "sourceLanguage": "ur", "source": {"pdfPage": 11, "printedPage": "7"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s011-h1", "hpe11-s011-p2", "hpe11-s011-h3", "hpe11-s011-p4", "hpe11-s011-p5", "hpe11-s011-p6", "hpe11-s011-p7", "hpe11-s011-p8", "hpe11-s011-p9", "hpe11-s011-p10", "hpe11-s011-p11", "hpe11-s011-h12", "hpe11-s011-p13"]}], "equations": [], "sourceNote": "Printed page 7: heart diseases introduction and list of eight diseases (English names printed as in the book, including “Cordial Asthma”, “Arterial Fibrillation”, “Value Blockage”); the heading “علامات” at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded; photographs/cartoons are not reproduced unless noted.", "review": {"reviewedAtUtc": "2026-10-13T02:25:04.849283+00:00", "scope": "Scan 11 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("دل کی بیماریاں، علامات اور وجوہات","Heart Diseases, Symptoms and Causes","د زړه ناروغۍ، نښې او لاملونه",{"id": "hpe11-s011-h1", "kind": "heading"}),
hpe11Pair("آج کل کے جدید دور میں جہاں انسان نے اپنے لیے سہولتیں پیدا کی ہیں وہاں ناقص خوراک اور آرام طلبی کی وجہ سے بیماریوں کی شرح میں بھی اضافہ ہوا ہے۔ دوسری بیماریوں کی طرح امراضِ قلب کا بھی انسانی زندگی کے ساتھ ہمیشہ سے تعلق رہا ہے مگر عصرِ حاضر کے جدید اور غیر فطری طرزِ حیات کو اپنانے والے انسانوں میں امراضِ قلب کی شرح جس قدر آج بلند ہے شاید انسانی تاریخ میں پہلے کبھی نہ تھی۔ ذیل میں دل کی چند اہم بیماریاں، ان کے علامات اور وجوہات کا ذکر کیا جا رہا ہے۔","In today’s modern age, where man has created comforts for himself, the rate of diseases has also increased because of poor diet and love of ease. Like other diseases, heart diseases have always been connected with human life, but the rate of heart disease among people who adopt the modern and unnatural lifestyle of the present age is perhaps higher today than ever before in human history. Below, a few important heart diseases, their symptoms and causes are described.","په نننۍ نوې دوره کې چېرته چې انسان د خپل ځان لپاره اسانتیاوې پیدا کړې، هلته د ناقص خوراک او آرام‌طلبۍ له امله د ناروغیو کچه هم زیاته شوې ده. لکه د نورو ناروغیو غوندې د زړه ناروغۍ هم تل د انساني ژوند سره اړیکه لرلې خو د اوسني عصر نوي او غیر فطري ژوند طرز اختیارونکو خلکو کې د زړه د ناروغیو کچه نن څومره لوړه ده شاید د انساني تاریخ کې مخکې هیڅکله نه وه. لاندې د زړه څو مهمې ناروغۍ، د هغو نښې او لاملونه یادېږي.",{"id": "hpe11-s011-p2", "sourceGap": {"note": "A cartoon of two hearts beside the first paragraph is not reproduced."}}),
hpe11Pair("دل کی بیماریاں یا امراضِ قلب","Heart Diseases (Cardiac Diseases)","د زړه ناروغۍ یا قلبي ناروغۍ",{"id": "hpe11-s011-h3", "kind": "heading"}),
hpe11Pair("i۔ قلبی دورہ یا ہارٹ اٹیک (Heart Attack)","i. Cardiac arrest or heart attack (Heart Attack)","i. قلبي حمله یا هارټ اټک (Heart Attack)",{"id": "hpe11-s011-p4", "listGroup": "hd"}),
hpe11Pair("ii۔ دل کا درد (Angina Pectoris)","ii. Heart pain (Angina Pectoris)","ii. د زړه درد (Angina Pectoris)",{"id": "hpe11-s011-p5", "listGroup": "hd"}),
hpe11Pair("iii۔ قلبی دمہ (Cordial Asthma)","iii. Cardiac asthma (“Cordial Asthma” as printed)","iii. قلبي ربو (Cordial Asthma)",{"id": "hpe11-s011-p6", "listGroup": "hd"}),
hpe11Pair("iv۔ دل کی غلاف کی سوزش (Pericarditis)","iv. Inflammation of the heart’s covering (Pericarditis)","iv. د زړه د پوښ سوځېدنه (Pericarditis)",{"id": "hpe11-s011-p7", "listGroup": "hd"}),
hpe11Pair("v۔ دل کے شریانوں کا سکڑنا (Arterial Fibrillation)","v. Narrowing of the arteries of the heart (“Arterial Fibrillation” as printed)","v. د زړه د شریانونو ټنګېدل (Arterial Fibrillation)",{"id": "hpe11-s011-p8", "listGroup": "hd"}),
hpe11Pair("vi۔ دل کے والو میں رکاوٹ (Value Blockage)","vi. Blockage in the heart’s valve (“Value Blockage” as printed)","vi. د زړه په والو کې خنډ (Value Blockage)",{"id": "hpe11-s011-p9", "listGroup": "hd"}),
hpe11Pair("vii۔ دل کا بڑھ جانا (Cardiomegaly)","vii. Enlargement of the heart (Cardiomegaly)","vii. د زړه لوېدل (Cardiomegaly)",{"id": "hpe11-s011-p10", "listGroup": "hd"}),
hpe11Pair("viii۔ بلند فشارِ خون یا ہائی بلڈ پریشر (High Blood Pressure)","viii. High blood pressure (High Blood Pressure)","viii. لوړ د وینې فشار (High Blood Pressure)",{"id": "hpe11-s011-p11", "listGroup": "hd"}),
hpe11Pair("علامات","Symptoms","نښې",{"id": "hpe11-s011-h12", "kind": "heading"}),
hpe11Pair("جس طرح دل کے امراض مختلف نوعیت کے ہیں اس طرح ان کی علامات بھی مختلف ہوتی ہیں اور اس بات کا","Just as heart diseases are of different kinds, their symptoms too are different, and this matter","لکه څنګه چې د زړه ناروغۍ بېلابېل ډوله دي همداسې د هغو نښې هم بېلابېلې دي او دا خبره",{"id": "hpe11-s011-p13", "sourceGap": {"note": "The sentence continues on the next page (printed page 8: “فیصلہ تشخیص کے بعد ہی کیا جا سکتا ہے …”)."}})
]});
