hpe11AddSection("hpe11-u01",{"id": "hpe11-s016-diabetes-3", "title": "Calories of food components; calorie table", "headingUrdu": "غذائی اجزا کی کیلوریز", "headingPashto": "د غذايي اجزاوو کالوري", "sourceLanguage": "ur", "source": {"pdfPage": 16, "printedPage": "12"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s016-p1", "hpe11-s016-p2", "hpe11-s016-p3", "hpe11-s016-p4"]}, {"type": "table", "index": 0}, {"type": "paragraphs", "ids": ["hpe11-s016-p5", "hpe11-s016-p6"]}], "equations": [], "tables": [{"caption": "Calories obtained from food ingredients (per 100 grams)", "captionUrdu": "غذائی اجزاء سے حاصل ہونے والے حرارے (100 گرام)", "captionPashto": "له غذايي اجزاوو ترلاسه کېدونکې حرارې (۱۰۰ ګرام)", "headers": [{"en": "Ingredient", "ur": "اجزا", "ps": "اجزا"}, {"en": "Calories", "ur": "حرارے", "ps": "حرارې"}], "rows": [[{"en": "Wheat", "ur": "گندم", "ps": "غنم"}, {"en": "0.36", "ur": "0.36", "ps": "0.36"}], [{"en": "Eggs", "ur": "انڈے", "ps": "هګۍ"}, {"en": "148", "ur": "148", "ps": "148"}], [{"en": "Mutton", "ur": "چھوٹا گوشت", "ps": "وړوکې غوښه"}, {"en": "163", "ur": "163", "ps": "163"}], [{"en": "Fish", "ur": "مچھلی", "ps": "کب"}, {"en": "176", "ur": "176", "ps": "176"}], [{"en": "Beans", "ur": "لوبیا", "ps": "لوبیا"}, {"en": "35", "ur": "35", "ps": "35"}], [{"en": "Butter", "ur": "مکھن", "ps": "کوچه"}, {"en": "715", "ur": "715", "ps": "715"}]]}], "sourceNote": "Printed page 12: calories per gram, one table (the printed header “100 گرام” spans the ingredient/calorie columns; the wheat entry reads 0.36 as printed) and two closing paragraphs. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:26:41.215759+00:00", "scope": "Scan 16 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("ایک گرام پروٹین میں 4 حرارے","In one gram of protein: 4 calories","په یو ګرام پروټین کې ۴ حرارې",{"id": "hpe11-s016-p1", "listGroup": "cl"}),
hpe11Pair("ایک گرام نشاستہ میں 4.1 حرارے","In one gram of starch: 4.1 calories","په یو ګرام نشاسته کې ۴.۱ حرارې",{"id": "hpe11-s016-p2", "listGroup": "cl"}),
hpe11Pair("ایک گرام چکنائی میں 9.3 حرارے","In one gram of fat: 9.3 calories","په یو ګرام غوړي کې ۹.۳ حرارې",{"id": "hpe11-s016-p3", "listGroup": "cl"}),
hpe11Pair("اس ترتیب سے شوگر کے مریض کو روزانہ 1500 حرارے پورے کرنے کے لیے خوراک دینی ضروری ہے۔ درج ذیل اجزاء کی کیلوریز دی گئی ہیں۔ اس کے مطابق چارٹ بنا کر شوگر کے مریض کو دیا جائے۔","In this way food must be given to a sugar patient to make up 1500 calories daily. The calories of the following ingredients are given. According to them a chart should be made and given to the sugar patient.","پدې ترتیب د شوګر ناروغ ته هره ورځ ۱۵۰۰ حرارې پوره کولو لپاره خوراک ورکول اړین دي. د لاندې اجزاوو کالوري ورکړل شوي. د هغو سره سم چارټ جوړ کړای شي او د شوګر ناروغ ته ورکړای شي.",{"id": "hpe11-s016-p4"}),
hpe11Pair("شوگر کے مریض کو دن میں 1500 کیلوریز سے زیادہ خوراک استعمال نہیں کرنی چاہیے اور یہ بھی تین وقفوں سے استعمال کریں۔ ڈاکٹر کی ہدایت کے مطابق دوائی، ورزش اور نیند کا خیال رکھیں۔","A sugar patient should not consume more than 1500 calories of food in a day, and this too should be taken in three intervals. According to the doctor’s instruction take care of medicine, exercise and sleep.","د شوګر ناروغ باید په ورځ کې له ۱۵۰۰ کالوریو زیات خوراک ونه کاروي او دا هم په دریو وختونو کارول پکار دي. د ډاکټر د لارښوونې سره سم د درملو، تمرین او خوب پام وساتئ.",{"id": "hpe11-s016-p5"}),
hpe11Pair("1500 کیلوریز حاصل کرنے کے لیے غذائی چارٹ دیا گیا ہے۔ اس کے مطابق خوراک کو عمر، جنس اور پیشہ کو مدنظر رکھتے ہوئے ایڈجسٹ کریں۔ خوراک میں رد و بدل کر کے استعمال کریں۔","A dietary chart is given for obtaining 1500 calories. According to it adjust the food keeping in view age, sex and occupation. Use it by varying the food.","د ۱۵۰۰ کالوریو ترلاسه کولو لپاره غذايي چارټ ورکړل شوی. د هغه سره سم خوراک د عمر، جنس او مسلک په پام کې نیولو سره سمبال کړئ. په خوراک کې بدلون راوستلو سره یې وکاروئ.",{"id": "hpe11-s016-p6"})
]});
