hpe11AddSection("hpe11-u02",{"id": "hpe11-s020-resp-1", "title": "Organs of the respiratory system; the nose", "headingUrdu": "نظامِ تنفس کے اعضاء؛ ناک", "headingPashto": "د تنفسي نظام غړي؛ پوزه", "sourceLanguage": "ur", "source": {"pdfPage": 20, "printedPage": "16"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s020-p1", "hpe11-s020-p2"]}, {"type": "figure", "index": 0}, {"type": "paragraphs", "ids": ["hpe11-s020-h3", "hpe11-s020-p4"]}], "equations": [], "figures": [{"id": "hpe11-s020-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 460 290\" role=\"img\" aria-label=\"Labelled respiratory system: nose, mouth, trachea (windpipe), lungs and diaphragm\" style=\"width:100%;max-width:460px;height:auto;background:#fff\"><circle cx=\"210\" cy=\"50\" r=\"30\" fill=\"#ffe0d6\" stroke=\"#8d6e63\"/><path d=\"M140 240 Q140 120 210 115 Q280 120 280 240 Z\" fill=\"#ffe0d6\" stroke=\"#8d6e63\"/><rect x=\"204\" y=\"60\" width=\"12\" height=\"70\" fill=\"#4a7ab5\"/><ellipse cx=\"182\" cy=\"165\" rx=\"24\" ry=\"42\" fill=\"#b05f8e\" stroke=\"#6a1b4d\"/><ellipse cx=\"238\" cy=\"165\" rx=\"24\" ry=\"42\" fill=\"#b05f8e\" stroke=\"#6a1b4d\"/><path d=\"M158 215 Q210 190 262 215 L262 240 L158 240 Z\" fill=\"#e57373\" stroke=\"#b71c1c\"/><text x=\"210\" y=\"22\" font-size=\"13\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Respiratory system</text><line x1=\"236\" y1=\"62\" x2=\"330\" y2=\"52\" stroke=\"#444\"/><text x=\"335\" y=\"56\" font-size=\"13\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Nose</text><line x1=\"226\" y1=\"72\" x2=\"330\" y2=\"82\" stroke=\"#444\"/><text x=\"335\" y=\"86\" font-size=\"13\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Mouth</text><line x1=\"216\" y1=\"110\" x2=\"330\" y2=\"116\" stroke=\"#444\"/><text x=\"335\" y=\"120\" font-size=\"13\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Trachea</text><line x1=\"182\" y1=\"170\" x2=\"90\" y2=\"140\" stroke=\"#444\"/><text x=\"10\" y=\"136\" font-size=\"13\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Lungs</text><line x1=\"170\" y1=\"228\" x2=\"90\" y2=\"262\" stroke=\"#444\"/><text x=\"10\" y=\"270\" font-size=\"13\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Diaphragm</text></svg>", "caption": "The respiratory system (Nose, Mouth, Trachea, Lungs, Diaphragm)", "captionUrdu": "نظامِ تنفس: ناک، منہ، ہوا کی نالی، پھیپھڑے، ڈایا فرام", "captionPashto": "تنفسي نظام: پوزه، خوله، د هوا نلۍ، سږي، ډایافرام", "labels": [{"en": "Nose", "ur": "ناک", "ps": "پوزه"}, {"en": "Mouth", "ur": "منہ", "ps": "خوله"}, {"en": "Trachea", "ur": "ہوا کی نالی", "ps": "د هوا نلۍ"}, {"en": "Lungs", "ur": "پھیپھڑے", "ps": "سږي"}, {"en": "Diaphragm", "ur": "ڈایا فرام", "ps": "ډایافرام"}], "sourceGap": {"note": "Redrawn as a simple coded diagram; the original is an anatomical outline picture with the same five labels (English and Urdu)."}}], "sourceNote": "Printed page 16: list of eight organs of the respiratory system, the labelled diagram, and the paragraph on the nose. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:26:43.179285+00:00", "scope": "Scan 20 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("نظامِ تنفس میں مندرجہ ذیل اعضاء حصہ لیتے ہیں:","The following organs take part in the respiratory system:","په تنفسي نظام کې لاندې غړي برخه اخلي:",{"id": "hpe11-s020-p1"}),
hpe11Pair("1۔ ناک 2۔ منہ 3۔ حلق 4۔ آلہ صوت 5۔ ہوا کی نالی 6۔ سانس کی نالی 7۔ پھیپھڑے 8۔ ڈایا فرام","1. Nose 2. Mouth 3. Throat 4. Voice box 5. Windpipe 6. Breathing tube 7. Lungs 8. Diaphragm","۱. پوزه ۲. خوله ۳. ستوني ۴. غږ آله ۵. د هوا نلۍ ۶. د ساه نلۍ ۷. سږي ۸. ډایافرام",{"id": "hpe11-s020-p2", "listGroup": "rg"}),
hpe11Pair("1۔ ناک (Nose):","1. Nose (Nose):","۱. پوزه (Nose):",{"id": "hpe11-s020-h3", "kind": "heading"}),
hpe11Pair("ناک سانس لینے کا ذریعہ ہے۔ ناک کے پہلے حصے میں بال ہوتے ہیں جو فلٹر کا کام کرتے ہیں۔ اس طرح ناک میں آگے ایک لعاب دار جھلی موجود ہوتی ہے جو ناک کو ہر وقت نم رکھتی ہے۔ ناک میں موجود خون کی باریک نالیاں ہوا کے درجہ حرارت کو انسانی جسم کے درجہ حرارت پر لانے کا کام سر انجام دیتی ہیں۔ اس طرح یہ ہوا پھیپھڑوں میں پہنچ کر نقصان نہیں کرتی۔","The nose is the means of breathing. In the first part of the nose there are hairs which act as a filter. In the same way, further on in the nose there is a mucous membrane which keeps the nose moist all the time. The fine blood vessels in the nose bring the temperature of the air to the temperature of the human body. In this way this air does not do harm on reaching the lungs.","پوزه د ساه اخیستو وسیله ده. د پوزې په لومړۍ برخه کې وېښتان وي چې د فلټر کار کوي. همداسې په پوزه کې مخکې یوه لاړه‌دار پرده موجوده وي چې پوزه تل لنده ساتي. په پوزه کې موجودې د وینې نازکې نلۍ د هوا د تودوخې درجه د انسان د بدن په تودوخه رسولو کار سرته رسوي. په دې ډول دا هوا سږو ته رسېدو سره زیان نه کوي.",{"id": "hpe11-s020-p4"})
]});
