hpe11AddSection("hpe11-u04",{"id": "hpe11-s036-emergency-3", "title": "Precautions under rubble (iv–vi); precautions after a blast", "headingUrdu": "ملبے کے نیچے احتیاطی تدابیر (iv–vi)؛ دھماکے کے بعد کی حفاظتی تدابیر", "headingPashto": "د ملبې لاندې احتیاطي تدبیرونه (iv–vi)؛ د چاودنې وروسته ساتنیز تدبیرونه", "sourceLanguage": "ur", "source": {"pdfPage": 36, "printedPage": "32"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s036-p1", "hpe11-s036-p2", "hpe11-s036-p3", "hpe11-s036-h4", "hpe11-s036-p5", "hpe11-s036-p6", "hpe11-s036-p7", "hpe11-s036-p8"]}], "equations": [], "sourceNote": "Printed page 32: end of precautions under rubble (iv–vi) with a rescue photograph, and the start of protective measures after a blast (i–iv). English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:33:07.119264+00:00", "scope": "Scan 36 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("iv۔ اگر ممکن ہو تو موبائل کی فلش لائٹ سے اشارہ کریں تاکہ ریسکیو ٹیم آپ کی موجودگی کے بارے میں جان سکے۔","iv. If possible, signal with the flashlight of the mobile so that the rescue team can know of your presence.","iv. که ممکن وي نو د موبایل د فلش لایټ په مټ اشاره وکړئ ترڅو ریسکیو ټیم ستاسو د شتون په اړه پوه شي.",{"id": "hpe11-s036-p1", "listGroup": "rb"}),
hpe11Pair("v۔ غیر ضروری حرکت سے پرہیز کریں۔","v. Avoid unnecessary movement.","v. له غیر ضروري حرکت ډډه وکړئ.",{"id": "hpe11-s036-p2", "listGroup": "rb"}),
hpe11Pair("vi۔ اگر ممکن ہو تو سیٹی بجائیں۔","vi. If possible, blow a whistle.","vi. که ممکن وي نو سیټۍ وغږوئ.",{"id": "hpe11-s036-p3", "listGroup": "rb", "sourceGap": {"note": "A photograph of rescuers working at a collapsed building is not reproduced."}}),
hpe11Pair("دھماکے کے بعد کی حفاظتی تدابیر:","Protective Measures after a Blast:","د چاودنې وروسته ساتنیز تدبیرونه:",{"id": "hpe11-s036-h4", "kind": "heading"}),
hpe11Pair("i۔ نیچے جھک جائیں اور محفوظ جگہ تلاش کریں۔","i. Bend down and look for a safe place.","i. ښکته کږ شئ او خوندي ځای ولټوئ.",{"id": "hpe11-s036-p5", "listGroup": "ab"}),
hpe11Pair("ii۔ عمارت کو جتنا جلد ممکن ہو چھوڑ دیں۔ اپنی قیمتی اشیاء کی فکر نہ کریں انھیں چھوڑ دیں۔","ii. Leave the building as quickly as possible. Do not worry about your valuables; leave them.","ii. ودانۍ تر هغه ژر چې ممکن وي پرېږدئ. د خپلو قیمتي شیانو فکر مه کوئ هغه پرېږدئ.",{"id": "hpe11-s036-p6", "listGroup": "ab"}),
hpe11Pair("iii۔ یاد رکھیں ایک دھماکے کے بعد دوسرا دھماکہ ہونے کا خدشہ رہتا ہے اس لیے دھماکے والی جگہ کی طرف نہ جائیں۔","iii. Remember that after one blast there is a danger of a second blast, so do not go towards the place of the blast.","iii. یاد ولرئ د یوې چاودنې وروسته د دویمې چاودنې خدشه پاتې کېږي له دې امله د چاودنې ځای لوري ته مه ځئ.",{"id": "hpe11-s036-p7", "listGroup": "ab"}),
hpe11Pair("iv۔ دروازے احتیاط سے کھولیں کوئی چیز آپ پر گر کر آپ کو زخمی کر سکتا ہے۔","iv. Open doors carefully; something may fall on you and injure you.","iv. دروازې په احتیاط سره پرانیزئ کوم شی پر تاسو لوېدو سره تاسو ټپي کولای شي.",{"id": "hpe11-s036-p8", "listGroup": "ab", "sourceGap": {"note": "The list continues on the next page (printed page 33)."}})
]});
