hpe11AddSection("hpe11-u04",{"id": "hpe11-s038-emergency-5", "title": "Tourniquet: method and diagram", "headingUrdu": "ٹورنی کویٹ: طریقہ اور خاکہ", "headingPashto": "ټورنیکیټ: طریقه او انځور", "sourceLanguage": "ur", "source": {"pdfPage": 38, "printedPage": "34"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s038-p1", "hpe11-s038-p2", "hpe11-s038-p3", "hpe11-s038-p4"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s038-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 300\" role=\"img\" aria-label=\"Tourniquet in four steps: 1) bandage wound around the limb and tie a knot; 2) pass a stick under the knot; 3) twist the stick to tighten; 4) fasten the stick in place\" style=\"width:100%;max-width:520px;height:auto;background:#fff\"><text x=\"260\" y=\"22\" font-size=\"18\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">Tourniquet</text><path d=\"M40 90 q60 -30 120 0 l0 40 q-60 30 -120 0 Z\" fill=\"#ffe0d6\" stroke=\"#8d6e63\" stroke-width=\"2\"/><rect x=\"88\" y=\"86\" width=\"24\" height=\"46\" rx=\"4\" fill=\"#c8e6c9\" stroke=\"#2e7d32\"/><text x=\"50\" y=\"72\" font-size=\"16\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">1</text><path d=\"M300 90 q60 -30 120 0 l0 40 q-60 30 -120 0 Z\" fill=\"#ffe0d6\" stroke=\"#8d6e63\" stroke-width=\"2\"/><rect x=\"348\" y=\"86\" width=\"24\" height=\"46\" rx=\"4\" fill=\"#c8e6c9\" stroke=\"#2e7d32\"/><line x1=\"330\" y1=\"64\" x2=\"400\" y2=\"130\" stroke=\"#5d4037\" stroke-width=\"6\"/><text x=\"310\" y=\"72\" font-size=\"16\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">2</text><path d=\"M40 210 q60 -30 120 0 l0 40 q-60 30 -120 0 Z\" fill=\"#ffe0d6\" stroke=\"#8d6e63\" stroke-width=\"2\"/><rect x=\"88\" y=\"206\" width=\"24\" height=\"46\" rx=\"4\" fill=\"#c8e6c9\" stroke=\"#2e7d32\"/><line x1=\"70\" y1=\"184\" x2=\"140\" y2=\"250\" stroke=\"#5d4037\" stroke-width=\"6\"/><text x=\"50\" y=\"192\" font-size=\"16\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">3</text><path d=\"M300 210 q60 -30 120 0 l0 40 q-60 30 -120 0 Z\" fill=\"#ffe0d6\" stroke=\"#8d6e63\" stroke-width=\"2\"/><rect x=\"348\" y=\"206\" width=\"24\" height=\"46\" rx=\"4\" fill=\"#c8e6c9\" stroke=\"#2e7d32\"/><line x1=\"330\" y1=\"184\" x2=\"400\" y2=\"250\" stroke=\"#5d4037\" stroke-width=\"6\"/><text x=\"310\" y=\"192\" font-size=\"16\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">4</text><path d=\"M92 142 q4 20 -2 30 M96 145 q4 14 0 26\" stroke=\"#c62828\" stroke-width=\"3\" fill=\"none\"/></svg>", "caption": "Tourniquet: four steps (1–4)", "captionUrdu": "ٹورنی کویٹ: چار مراحل (1–4)", "captionPashto": "ټورنیکیټ: څلور پړاوونه (۱–۴)", "labels": [{"en": "Tourniquet", "ur": "ٹورنی کویٹ", "ps": "ټورنیکیټ"}], "sourceGap": {"note": "Simplified coded schematic of the four numbered line drawings (bandage tied around the limb, a stick inserted, twisted, and fixed); the original drawings are not reproduced."}}], "sourceNote": "Printed page 34: tourniquet method ii–v and the four-step tourniquet illustration (labelled “Tourniquet”, steps 1–4). English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:33:08.099915+00:00", "scope": "Scan 38 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("ii۔ خون روکنے کے لیے دباؤ ڈالنے کی ٹھیک مقررہ جگہ پر چھوٹی سی سخت گدی رکھیں۔","ii. To stop the blood, place a small hard pad on the exactly fixed place for applying pressure.","ii. د وینې بندولو لپاره د فشار اچولو په ټاکل شوي سم ځای کوچنۍ کلکه ګدۍ کېږدئ.",{"id": "hpe11-s038-p1", "listGroup": "tq"}),
hpe11Pair("iii۔ زخمی ہاتھ یا پاؤں پر پتلی پٹی یا تسمہ لپیٹ دیں۔ اس پٹی یا تسمہ کا درمیان کا حصہ گدی پر ہونا چاہیے۔ جہاں پٹی رکھی ہو اس کی مخالف سمت میں گرہ لگا دیں۔","iii. Wrap a thin bandage or strap on the injured hand or foot. The middle part of this bandage or strap should be on the pad. Tie a knot on the side opposite to where the bandage is placed.","iii. په ټپي لاس یا پښه نازکه پټۍ یا تسمه ونغاړئ. د دې پټۍ یا تسمې منځنۍ برخه باید په ګدۍ وي. چېرته چې پټۍ ایښودل شوې د هغې په مخالفه خوا غوټه وتړئ.",{"id": "hpe11-s038-p2", "listGroup": "tq"}),
hpe11Pair("iv۔ شریان پر دباؤ بڑھائیں تاکہ خون رک جائے۔","iv. Increase pressure on the artery so that the blood stops.","iv. پر شریان فشار زیات کړئ ترڅو وینه ودرېږي.",{"id": "hpe11-s038-p3", "listGroup": "tq"}),
hpe11Pair("v۔ مریض کو جلد از جلد ہسپتال منتقل کرنے کی کوشش کریں۔ تاکہ بر وقت علاج سے اس کی جان بچائی جا سکے۔","v. Try to transfer the patient to hospital as soon as possible, so that his life can be saved by timely treatment.","v. ناروغ ته ژر تر ژره روغتون ته لېږدولو هڅه وکړئ. ترڅو په وخت درملنې سره د هغه ژوند وژغورل شي.",{"id": "hpe11-s038-p4", "listGroup": "tq"})
]});
