hpe11AddSection("hpe11-u07",{"id": "hpe11-s068-race200-3", "title": "Skills of the 200-metre race", "headingUrdu": "200 میٹر دوڑ کی مہارتیں", "headingPashto": "د ۲۰۰ مترو منډې مهارتونه", "sourceLanguage": "ur", "source": {"pdfPage": 68, "printedPage": "66"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s068-h1", "hpe11-s068-h2", "hpe11-s068-p3", "hpe11-s068-h4", "hpe11-s068-p5", "hpe11-s068-h6", "hpe11-s068-p7", "hpe11-s068-p8"]}], "equations": [], "sourceNote": "Printed page 66: skills of the 200-metre race (on your marks, set, fire/whistle and finish); the lower half of the page is blank. The footer strip is cropped in the scan. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:41:19.409527+00:00", "scope": "Scan 68 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("200 میٹر دوڑ کی مہارتیں","Skills of the 200-Metre Race","د ۲۰۰ مترو منډې مهارتونه",{"id": "hpe11-s068-h1", "kind": "heading"}),
hpe11Pair("1۔ آن یور مارکس:","1. On Your Marks:","۱. آن یور مارکس:",{"id": "hpe11-s068-h2", "kind": "heading"}),
hpe11Pair("کھلاڑی سٹارٹنگ لائن پر کروچ پوزیشن میں بیٹھے گا۔ دونوں پاؤں زمین پر ہوں گے۔ ہاتھ لائن سے پیچھے ہوں گے جسم حالت سکون میں ہوگا۔ انگوٹھے اندر کی طرف اور انگلیاں باہر کی طرف ہوں گی۔","The player will sit on the starting line in the crouch position. Both feet will be on the ground. The hands will be behind the line and the body will be in a state of rest. The thumbs will be towards the inside and the fingers towards the outside.","لوبغاړی به د پیل پر کرښه د کروچ په حالت کې کېني. دواړه پښې به په ځمکه وي. لاسونه به د کرښې شاته وي بدن به د سکون په حالت کې وي. ګوتې به دننه لوري ته او نورې ګوتې به بهر لوري ته وي.",{"id": "hpe11-s068-p3"}),
hpe11Pair("2۔ سیٹ:","2. Set:","۲. سیټ:",{"id": "hpe11-s068-h4", "kind": "heading"}),
hpe11Pair("جو نہی سیٹ کا اعلان ہوں کھلاڑی جسم کو اوپر اٹھائے گا اور چھاتی کو لائن سے آگے نکالے گا۔","As soon as “Set” is announced, the player will raise his body and push his chest forward of the line.","همدا چې د سیټ اعلان وشي لوبغاړی به بدن پورته کوي او سینه به له کرښې مخکې وباسي.",{"id": "hpe11-s068-p5"}),
hpe11Pair("3۔ وسل / فائر:","3. Whistle / Fire:","۳. وسل / فایر:",{"id": "hpe11-s068-h6", "kind": "heading"}),
hpe11Pair("جب فائر کی آواز آئے کھلاڑی کا جسم جھکا ہو گا پہلے 100 میٹر تک رفتار میں اضافہ کی کوشش کرنی چاہیے اور جسم کو آہستہ آہستہ سیدھا کیا جائے۔","When the sound of the fire comes, the player’s body will be bent; up to the first 100 metres an effort should be made to increase speed and the body should be gradually straightened.","کله چې د فایر غږ راشي د لوبغاړي بدن به کږ وي لومړنیو ۱۰۰ مترو پورې په ګړندیتوب کې د زیاتوالي هڅه باید وشي او بدن ورو ورو سیده کړای شي.",{"id": "hpe11-s068-p7"}),
hpe11Pair("آخری 100 میٹر میں بازوؤں اور ٹانگوں کی بھرپور طاقت کا استعمال کیا جائے اور رفتار برقرار رکھی جائے۔ اختتام پر پہنچتے ہی چھاتی کو آگے کی طرف بڑھایا جائے اور اختتامی لکیر کو عبور کیا جائے۔","In the last 100 metres the full strength of the arms and legs should be used and the speed should be maintained. On reaching the end the chest should be pushed forward and the finishing line crossed.","په وروستیو ۱۰۰ مترو کې د لاسونو او پښو بشپړ ځواک وکارول شي او ګړندیتوب وساتل شي. پای ته رسېدو سره سم سینه مخکې لوري ته وغځول شي او د پای کرښه تېره شي.",{"id": "hpe11-s068-p8"})
]});
