hpe11AddSection("hpe11-u07",{"id": "hpe11-s076-relay-5", "title": "Baton exchange: visual and non-visual methods; correct and wrong ways", "headingUrdu": "بیٹن کی تبدیلی: بصری اور غیر بصری طریقہ؛ درست اور غلط طریقے", "headingPashto": "د بیټن بدلول: لیدنیز او غیر لیدنیز طریقه؛ سمې او غلطې طریقې", "sourceLanguage": "ur", "source": {"pdfPage": 76, "printedPage": "74"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s076-h1", "hpe11-s076-p2", "hpe11-s076-h3", "hpe11-s076-p4"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s076-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"Two panels with three numbered hand-and-baton drawings each: on the left a cross mark with the wrong way of exchanging the baton, on the right a tick mark with the correct way; below, three views of a hand gripping the baton\" style=\"width:100%;max-width:520px;height:auto;background:#fff\"><circle cx=\"130\" cy=\"30\" r=\"20\" fill=\"#333\"/><path d=\"M122 30 l16 0 M130 22 l0 16\" stroke=\"#fff\" stroke-width=\"3\" transform=\"rotate(45 130 30)\"/><text x=\"130\" y=\"76\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Wrong way</text><circle cx=\"390\" cy=\"30\" r=\"20\" fill=\"#333\"/><path d=\"M380 32 l8 8 l14 -16\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\"/><text x=\"390\" y=\"76\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Correct way</text><g><rect x=\"40\" y=\"110\" width=\"110\" height=\"14\" rx=\"7\" fill=\"#bdbdbd\" stroke=\"#333\"/><circle cx=\"70\" cy=\"150\" r=\"22\" fill=\"#e0c3a8\" stroke=\"#6d4c41\"/><text x=\"95\" y=\"210\" font-size=\"16\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">1</text><rect x=\"200\" y=\"110\" width=\"110\" height=\"14\" rx=\"7\" fill=\"#bdbdbd\" stroke=\"#333\"/><circle cx=\"230\" cy=\"150\" r=\"22\" fill=\"#e0c3a8\" stroke=\"#6d4c41\"/><text x=\"255\" y=\"210\" font-size=\"16\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">2</text><rect x=\"360\" y=\"110\" width=\"110\" height=\"14\" rx=\"7\" fill=\"#bdbdbd\" stroke=\"#333\"/><circle cx=\"390\" cy=\"150\" r=\"22\" fill=\"#e0c3a8\" stroke=\"#6d4c41\"/><text x=\"415\" y=\"210\" font-size=\"16\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"700\" fill=\"#111\">3</text></g></svg>", "caption": "Baton exchange: wrong way (cross) and correct way (tick); three grips (1–3)", "captionUrdu": "بیٹن تبدیل کرنے کا غلط اور درست طریقہ؛ تین گرفتیں (1–3)", "captionPashto": "د بیټن بدلولو غلطه او سمه طریقه؛ درې نیونې (۱–۳)", "labels": [{"en": "Wrong way", "ur": "غلط طریقہ", "ps": "غلطه طریقه"}, {"en": "Correct way", "ur": "درست طریقہ", "ps": "سمه طریقه"}], "sourceGap": {"note": "Simplified coded schematic of the photographic hand drawings (cross and tick marks with three numbered grips); the photographs are not reproduced."}}], "sourceNote": "Printed page 74: visual and non-visual methods of baton exchange and the illustration of the correct and wrong ways with three numbered grips. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:44:27.045425+00:00", "scope": "Scan 76 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("i۔ بصری طریقہ:","i. Visual Method:","i. لیدنیز طریقه:",{"id": "hpe11-s076-h1", "kind": "heading"}),
hpe11Pair("یہ طریقہ 4 × 100 میٹر یا اس سے زیادہ فاصلہ کی ڈاک دوڑ میں استعمال کیا جاتا ہے چونکہ اس دوڑ میں کھلاڑی کی رفتار یکساں نہیں رہتی۔ اس لیے کھلاڑی کے قریب پہنچنے پر اس کا ساتھی اندازہ کرنے کے لیے پیچھے دیکھتے ہوئے دوڑ کا آغاز کرتا ہے اور اسی دوران اپنے ساتھی سے بیٹن وصول کرتا ہے۔","This method is used in a relay race of 4 × 100 metres or a longer distance, because in this race the player’s speed does not remain uniform. Therefore when the player comes near, his fellow player, looking back to judge, begins to run and during this receives the baton from his fellow player.","دا طریقه د ۴ × ۱۰۰ متره یا له هغې زیات واټن په ریلې منډه کې کارول کېږي ځکه چې په دې منډه کې د لوبغاړي ګړندیتوب یو شان نه پاتې کېږي. له همدې امله د لوبغاړي سره نږدې رسېدو په اټکل کولو لپاره د هغه ملګری شاته کتو سره د منډې پیل کوي او په همدې موده کې له خپل ملګري بیټن ترلاسه کوي.",{"id": "hpe11-s076-p2"}),
hpe11Pair("ii۔ غیر بصری طریقہ:","ii. Non-visual Method:","ii. غیر لیدنیز طریقه:",{"id": "hpe11-s076-h3", "kind": "heading"}),
hpe11Pair("یہ طریقہ ایسی دوڑ میں استعمال کیا جاتا ہے جن میں بیٹن دینے والے کی رفتار بہت تیز ہوتی ہے اور وصول کرنے والا کھلاڑی بغیر دیکھے بیٹن تبدیل کرتا ہے۔ بیٹن تبدیلی کا طریقہ چھوٹے فاصلے کی تیز ترین دوڑوں میں استعمال ہوتا ہے۔ بیٹن وصول کرنے والا اپنے ساتھی کے پہنچنے سے پہلے اپنی پوری رفتار سے دوڑ نا شروع کرتا ہے اور بیٹن کی تبدیلی بغیر دیکھے تقریباً پوری رفتار میں مکمل ہوتی ہے۔ یہ طریقہ عام طور سے 4 × 100 اور 4 × 400 میٹر دوڑ کے لیے موزوں تصور کیا جاتا ہے۔","This method is used in races in which the speed of the one giving the baton is very high and the player receiving changes the baton without looking. The method of baton exchange is used in the fastest races of short distances. The one receiving the baton begins to run at his full speed before his fellow player arrives, and the exchange of the baton is completed, without looking, almost at full speed. This method is generally considered suitable for the 4 × 100 and 4 × 400-metre races.","دا طریقه په داسې منډه کې کارول کېږي چې په هغو کې د بیټن ورکوونکي ګړندیتوب ډېر ګړندی وي او ترلاسه کوونکی لوبغاړی پرته له کتو بیټن بدلوي. د بیټن د بدلون طریقه د لنډ واټن په ګړندیو منډو کې کارول کېږي. بیټن ترلاسه کوونکی د خپل ملګري له رسېدو نه مخکې په خپل بشپړ ګړندیتوب منډې پیل کوي او د بیټن بدلون پرته له کتو نژدې په بشپړ ګړندیتوب کې بشپړېږي. دا طریقه عموماً د ۴ × ۱۰۰ او ۴ × ۴۰۰ مترو منډې لپاره مناسبه ګڼل کېږي.",{"id": "hpe11-s076-p4"})
]});
