hpe11AddSection("hpe11-u07",{"id": "hpe11-s083-shotput-4", "title": "Shot put: fouls 6–8; throwing skills (grip, standing throw, gliding, delivery)", "headingUrdu": "شاٹ پٹ: فاؤلز 6–8؛ گولہ پھینکنے کی مہارتیں", "headingPashto": "شاټ پټ: فاولونه ۶–۸؛ ګولۍ غورځولو مهارتونه", "sourceLanguage": "ur", "source": {"pdfPage": 83, "printedPage": "81"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s083-p1", "hpe11-s083-p2", "hpe11-s083-p3", "hpe11-s083-h4", "hpe11-s083-h5", "hpe11-s083-p6", "hpe11-s083-h7", "hpe11-s083-p8", "hpe11-s083-h9", "hpe11-s083-p10", "hpe11-s083-h11", "hpe11-s083-p12"]}], "equations": [], "sourceNote": "Printed page 81: shot-put fouls 6–8 and the four skills of throwing (grip, standing throw, gliding, delivery); the lower part of the page is blank. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:46:23.023947+00:00", "scope": "Scan 83 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("6۔ گولہ کے زمین پر گرنے سے پہلے سیکٹر چھوڑ دینا۔","6. Leaving the circle before the shot falls on the ground.","۶. د ګولۍ د ځمکې په لوېدو نه مخکې سکتور پرېښودل.",{"id": "hpe11-s083-p1", "listGroup": "fl"}),
hpe11Pair("7۔ گولہ پھینکنے کے بعد سیکٹر کو آگے سے کراس کرنا۔","7. Crossing the sector from the front after throwing the shot.","۷. د ګولۍ غورځولو وروسته سکتور له مخې نه تېرول.",{"id": "hpe11-s083-p2", "listGroup": "fl"}),
hpe11Pair("8۔ ممنوعہ ادویات استعمال کرنا۔","8. Using prohibited drugs.","۸. منع شوي درمل کارول.",{"id": "hpe11-s083-p3", "listGroup": "fl"}),
hpe11Pair("گولہ پھینکنے کی مہارتیں:","Skills of Throwing the Shot:","د ګولۍ غورځولو مهارتونه:",{"id": "hpe11-s083-h4", "kind": "heading"}),
hpe11Pair("گرفت:","Grip:","نیونه:",{"id": "hpe11-s083-h5", "kind": "heading"}),
hpe11Pair("گولہ انگلیوں کے پوروں سے پکڑا جائے گولہ کندھے کی لائن پر ہو اور گردن کے ساتھ لگا ہوا ہو۔","The shot should be held with the fingertips; the shot should be on the line of the shoulder and touching the neck.","ګولۍ د ګوتو په څوکو ونیول شي ګولۍ د اوږې په کرښه وي او له غاړې سره لګېدلې وي.",{"id": "hpe11-s083-p6"}),
hpe11Pair("کھڑے کھڑے پھینکنا:","Throwing While Standing:","ولاړ ولاړ غورځول:",{"id": "hpe11-s083-h7", "kind": "heading"}),
hpe11Pair("ابتدائی مشق کے طور پر گولے کو کھڑے کھڑے پھینکیں۔ بازو کو اوپر کی طرف سیدھا کرتے ہوئے آگے کی طرف پھیلائیں۔","As initial practice throw the shot while standing. Extend the arm forward, straightening it upwards.","د لومړنۍ تمرین په توګه ګولۍ ولاړ ولاړ وغورځوئ. لاس پورته لوري ته سیده کولو سره مخکې لوري ته وغځوئ.",{"id": "hpe11-s083-p8"}),
hpe11Pair("گلائیڈ نگ:","Gliding:","ګلایډنګ:",{"id": "hpe11-s083-h9", "kind": "heading"}),
hpe11Pair("گولہ پھینکتے وقت دائرے میں کھڑے اتھلیٹ کی کمر سیکٹر کی طرف، دایاں پاؤں آگے، بایاں پاؤں پیچھے، کمر جھکا کر اور چھاتی اٹھا کر گھڑی کے مخالف سمت (Anticlock wise) گھومتے ہوئے گولے کو سیکٹر کی طرف پھینکنے کو گلائیڈ نگ کہتے ہیں۔","At the time of throwing the shot, the athlete standing in the circle with his back towards the sector, the right foot forward and the left foot behind, bending the back and raising the chest and turning anticlockwise (Anticlock wise), throwing the shot towards the sector is called gliding.","د ګولۍ د غورځولو په وخت کې په دایره ولاړ اتلیټ ملا د سکتور لوري ته، ښي پښه مخکې، کیڼه پښه شاته، ملا کږولو او سینه پورته کولو سره د ګړۍ د مخالف لوري (Anticlock wise) ګرځېدو سره ګولۍ د سکتور لوري ته غورځول ګلایډنګ بلل کېږي.",{"id": "hpe11-s083-p10"}),
hpe11Pair("گولہ پھینکنا (Delivery):","Throwing the Shot (Delivery):","ګولۍ غورځول (Delivery):",{"id": "hpe11-s083-h11", "kind": "heading"}),
hpe11Pair("گلائیڈ کے مرحلے کے اختتام پر دائیں اور بائیں پاؤں کے زمین پر لگنے اور گلائیڈ سے حاصل کردہ قوت کی حرکت سے پھینکنے کا عمل شروع ہوتا ہے۔ دائیں ٹانگ اور بائیں بازو کے باہمی پھیلاؤ سے پھینکنے کا عمل شروع کرنا چاہیے۔ بائیں بازو کو چھاتی سے دور رکھیں اور اوپر اٹھائیں۔ کلائی کہنی سے اوپر اور گولہ پھینکتے وقت جسم پوری طرح اوپر کی جانب پھیلا ہو اور توازن کو قائم رکھا جائے۔","At the end of the glide stage, as the right and left feet touch the ground, the action of throwing begins with the movement of force gained from the glide. The action of throwing should begin with the mutual extension of the right leg and the left arm. Keep the left arm away from the chest and raise it. The wrist should be above the elbow, and at the time of throwing the shot the body should be fully extended upwards and balance should be maintained.","د ګلایډ د پړاو په پای کې د ښي او کیڼې پښې په ځمکه لګېدو او د ګلایډ نه ترلاسه شوي ځواک په حرکت سره د غورځولو بهیر پیلېږي. د ښي ښنګر او کیڼ لاس په متقابل غځېدو سره د غورځولو بهیر پیل کول پکار دي. کیڼ لاس له سینې لرې وساتئ او پورته یې کړئ. مړوند له څنګلې پورته او د ګولۍ د غورځولو په وخت بدن بشپړ پورته لوري ته غځول شوی وي او توازن وساتل شي.",{"id": "hpe11-s083-p12"})
]});
