hpe11AddSection("hpe11-u07",{"id": "hpe11-s088-longjump-2", "title": "Long jump: rules of the competition (1–4)", "headingUrdu": "لمبی چھلانگ: مقابلے کے قوانین (1–4)", "headingPashto": "اوږد ټوپ: د سیالۍ قوانین (۱–۴)", "sourceLanguage": "ur", "source": {"pdfPage": 88, "printedPage": "86"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s088-h1", "hpe11-s088-h2", "hpe11-s088-p3", "hpe11-s088-h4", "hpe11-s088-p5", "hpe11-s088-h6", "hpe11-s088-p7", "hpe11-s088-h8", "hpe11-s088-p9"]}], "equations": [], "sourceNote": "Printed page 86: long-jump competition rules 1–4 (draw, turns, use of the runway, time for completing a turn). The lower part of the page is blank. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:47:59.415141+00:00", "scope": "Scan 88 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("مقابلے کے قوانین:","Rules of the Competition:","د سیالۍ قوانین:",{"id": "hpe11-s088-h1", "kind": "heading"}),
hpe11Pair("1۔ قرعہ اندازی:","1. Draw:","۱. قرعه:",{"id": "hpe11-s088-h2", "kind": "heading"}),
hpe11Pair("لانگ جمپ میں باریاں قرعہ اندازی سے دی جاتی ہیں۔","In the long jump turns are given by draw.","په اوږد ټوپ کې نوبتونه په قرعه ورکول کېږي.",{"id": "hpe11-s088-p3"}),
hpe11Pair("2۔ باریاں:","2. Turns:","۲. نوبتونه:",{"id": "hpe11-s088-h4", "kind": "heading"}),
hpe11Pair("مقابلے میں اتھلیٹس کی تعداد 8 ہو تو ان کو 6-6 باریاں دی جائیں گی۔ اگر اتھلیٹس کی تعداد 8 سے زیادہ ہو تو ہر اتھلیٹ کو 3 - 3 باریاں دی جاتی ہیں اور 8 بہتر چھلانگ والے اتھلیٹس کو مزید 3 - 3 باریاں دی جاتی ہیں۔","If the number of athletes in the competition is 8, they will be given 6-6 turns each. If the number of athletes is more than 8, every athlete is given 3 - 3 turns and the 8 athletes with the better jumps are given a further 3 - 3 turns.","که په سیالۍ کې د اتلیټانو شمېر ۸ وي نو هغوی ته ۶–۶ نوبتونه ورکول کېږي. که د اتلیټانو شمېر له ۸ زیات وي نو هر اتلیټ ته ۳–۳ نوبتونه ورکول کېږي او ۸ غوره ټوپ لرونکو اتلیټانو ته نور ۳–۳ نوبتونه ورکول کېږي.",{"id": "hpe11-s088-p5"}),
hpe11Pair("3۔ رن وے کا استعمال:","3. Use of the Runway:","۳. د رن وې کارول:",{"id": "hpe11-s088-h6", "kind": "heading"}),
hpe11Pair("مقابلہ شروع ہونے سے پہلے ججوں کی نگرانی میں ہر اتھلیٹ کو مشق کے لیے 2-2 باریاں دی جاتی ہیں لیکن مقابلہ شروع ہونے کے بعد اتھلیٹس رن وے یا کھاڑہ کو مشق کے لیے استعمال نہیں کر سکتا۔","Before the competition begins, under the supervision of the judges, every athlete is given 2-2 turns for practice, but after the competition begins athletes cannot use the runway or the pit for practice.","د سیالۍ له پیل نه مخکې د ججانو په څارنه هر اتلیټ ته د تمرین لپاره ۲–۲ نوبتونه ورکول کېږي خو د سیالۍ له پیل وروسته اتلیټان رن وې یا کهاړه د تمرین لپاره نشي کارولای.",{"id": "hpe11-s088-p7"}),
hpe11Pair("4۔ باری مکمل کرنے کے لیے وقت:","4. Time for Completing a Turn:","۴. د نوبت د بشپړولو لپاره وخت:",{"id": "hpe11-s088-h8", "kind": "heading"}),
hpe11Pair("اتھلیٹ کا نام پکارے جانے اور جج کے اشارے کے بعد کوشش شروع کی جائے اور اتھلیٹ کو ایک منٹ کے اندر ہی اپنی کوشش شروع کرنی ہوگی ورنہ اسے ناکام تصور کیا جائے گا۔ تاہم اگر وہ چاہے تو مختص کردہ دورانیہ میں اپنی شروع کردہ کوشش روک کر دوڑنے کی راہداری سے باہر آ سکتا ہے اور پھر واپس اندر جا کر نئی کوشش شروع کر سکتا ہے۔ اگر اتھلیٹ مقررہ دورانیے کے اندر اندر اپنی کوشش شروع نہ کر سکے یا اپنی باری نہ لینا چاہے تو اسے ناکام کوشش تصور کیا جائے گا۔ لیکن اگر کوشش شروع ہونے کے ساتھ مقررہ وقت کی معیاد ختم ہو جائے تو ایسی کوشش صحیح تسلیم کی جائے گی۔","After the athlete’s name is called and the judge signals, the attempt should begin, and the athlete must begin his attempt within one minute or it will be considered a failure. However, if he wishes, within the allotted period he can stop an attempt he has begun and come out of the running corridor and then go back in and begin a new attempt. If the athlete cannot begin his attempt within the fixed period or does not want to take his turn, it will be considered a failed attempt. But if the fixed time expires as the attempt begins, such an attempt will be accepted as valid.","وروسته له دې چې د اتلیټ نوم واخیستل شي او جج اشاره وکړي هڅه پیل شي او اتلیټ باید په یوې دقیقې کې خپله هڅه پیل کړي که نه ناکامه ګڼل کېږي. خو که هغه وغواړي نو په ټاکل شوې مودې کې خپله پیل شوې هڅه ودروي او د منډو له دهلیز نه بهر راوځي او بیا بېرته دننه تللو سره نوې هڅه پیل کړای شي. که اتلیټ په ټاکلې مودې کې خپله هڅه پیل نه کړای شي یا خپل نوبت نه غواړي نو ناکامه هڅه ګڼل کېږي. خو که د هڅې له پیل سره د ټاکلي وخت موده پای ته ورسېږي نو داسې هڅه سمه منل کېږي.",{"id": "hpe11-s088-p9"})
]});
