hpe11AddSection("hpe11-u07",{"id": "hpe11-s090-longjump-4", "title": "Long jump: distances; the pit; diagram of the long-jump layout", "headingUrdu": "لمبی چھلانگ: فاصلے؛ اکھاڑہ؛ خاکہ", "headingPashto": "اوږد ټوپ: واټنونه؛ کهاړه؛ انځور", "sourceLanguage": "ur", "source": {"pdfPage": 90, "printedPage": "88"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s090-p1", "hpe11-s090-h2", "hpe11-s090-p3", "hpe11-s090-p4"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s090-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 560 380\" role=\"img\" aria-label=\"Plan of the long-jump area: the pit, the take-off board and the runway, with their dimensions: pit 9 m by 2.75 m, board 1.22 m by 20 cm, board to pit 1 m, runway 40 to 45 m long\" style=\"width:100%;max-width:560px;height:auto;background:#fff\"><rect x=\"140\" y=\"20\" width=\"190\" height=\"130\" fill=\"#fff\" stroke=\"#e65100\" stroke-width=\"2\"/><rect x=\"110\" y=\"190\" width=\"250\" height=\"26\" fill=\"#fff\" stroke=\"#e65100\" stroke-width=\"2\"/><rect x=\"140\" y=\"216\" width=\"190\" height=\"130\" fill=\"#fff\" stroke=\"#e65100\" stroke-width=\"2\"/><line x1=\"100\" y1=\"20\" x2=\"100\" y2=\"350\" stroke=\"#e65100\" stroke-dasharray=\"4 3\"/><text x=\"150\" y=\"16\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Pit</text><text x=\"360\" y=\"184\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Take-off board (1.22 m)</text><text x=\"150\" y=\"365\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Runway 40–45 m</text><text x=\"400\" y=\"100\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Pit length 9 m</text><text x=\"400\" y=\"114\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Pit width 2.75 m</text><text x=\"400\" y=\"170\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Board to pit 1 m</text><text x=\"400\" y=\"230\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Board 20 cm × 10 cm</text><text x=\"400\" y=\"290\" font-size=\"10\" text-anchor=\"start\" font-family=\"Arial,sans-serif\" font-weight=\"400\" fill=\"#111\">Runway width 1.22–1.25 m</text></svg>", "caption": "Long-jump layout: pit 9 m × 2.75 m, take-off board 1.22 m × 20 cm, 1 m gap, runway 40–45 m", "captionUrdu": "لمبی چھلانگ کا خاکہ: اکھاڑہ 9 × 2.75 میٹر، ٹیک آف بورڈ 1.22 میٹر × 20 سینٹی میٹر، 1 میٹر کا فاصلہ، دوڑنے کا راستہ 40–45 میٹر", "captionPashto": "د اوږد ټوپ انځور: کهاړه ۹ × ۲.۷۵ متره، ټیک آف بورډ ۱.۲۲ متره × ۲۰ سانتي متره، ۱ متر واټن، د منډو لار ۴۰–۴۵ متره", "labels": [], "sourceGap": {"note": "Simplified coded redrawing of the red line diagram, whose small Urdu labels (pit length 9 m, width 2.75 m, board-to-pit distance 1 m, board 20 cm and 10 cm, runway width 1.22/1.25 m, length 40–45 m) are rendered in English here."}}], "sourceNote": "Printed page 88: end of the description of the board distances, the pit, the indicator board used in international competitions, and the long-jump layout diagram (Urdu labels). English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:48:00.457757+00:00", "scope": "Scan 90 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("تختے سے اکھاڑے کے کنارے تک کا فاصلہ ایک میٹر سے کم نہ ہو۔ جبکہ تختے سے اکھاڑے کے آخری کنارہ تک کا درمیانی فاصلہ کم از کم دس میٹر ہو۔","The distance from the board to the edge of the pit should not be less than one metre, while the distance from the board to the far end of the pit should be at least ten metres.","له تختې نه د کهاړې تر څنډې پورې واټن له یو متر کم نه وي. پداسې حال کې چې له تختې نه د کهاړې تر وروستۍ څنډې پورې منځنی واټن لږ تر لږه لس متره وي.",{"id": "hpe11-s090-p1", "sourceGap": {"note": "The sentence completes the end of the take-off board description from printed page 87."}}),
hpe11Pair("3۔ اکھاڑہ:","3. The Pit:","۳. کهاړه:",{"id": "hpe11-s090-h2", "kind": "heading"}),
hpe11Pair("اکھاڑہ کی چوڑائی 2.75 میٹر اور لمبائی 9 میٹر ہو۔ اکھاڑہ میں نرم ریت یا بھر بھری مٹی ہو جس کی سطح ٹیک آف بورڈ کے برابر ہو۔ اکھاڑہ کی طرف عین ٹیک آف بورڈ کے ساتھ ریت یا نرم مٹی سے 10 سینٹی میٹر چوڑی تہہ لگائی جائے گی جو اس کی سطح سے 7 ملی میٹر اونچی ہوگی اور سامنے کی جانب اس کا زاویہ 45 درجے کا ہوگا۔ مٹی یا ریت کی تہہ کا مقصد یہ ہے کہ جب اتھلیٹ کا پاؤں تختے پر پڑے تو آسانی سے پتا چل سکے کہ آیا یہ فاؤل ہے یا نہیں۔","The width of the pit should be 2.75 metres and its length 9 metres. The pit should have soft sand or loose earth whose surface is level with the take-off board. A layer 10 centimetres wide of sand or soft earth will be laid on the pit side, right next to the take-off board, which will be 7 millimetres higher than its surface and whose angle on the front side will be 45 degrees. The purpose of the layer of earth or sand is that when the athlete’s foot falls on the board it can easily be known whether it is a foul or not.","د کهاړې پلنوالی ۲.۷۵ متره او اوږدوالی ۹ متره وي. په کهاړه کې نرمه شګه یا لټه خاورې وي چې سطحه یې د ټیک آف بورډ برابره وي. د کهاړې په لوري عین د ټیک آف بورډ سره د شګې یا نرمې خاورې ۱۰ سانتي متره پلنه ترټه ایښودل کېږي چې د هغې له سطحې ۷ ملي متره لوړه وي او مخکې لوري ته یې زاویه ۴۵ درجې وي. د خاورې یا شګې د ترټې موخه دا ده چې کله د اتلیټ پښه پر تختې ولګېږي نو په اسانۍ معلومېدای شي چې آیا دا فاول دی یا نه.",{"id": "hpe11-s090-p3"}),
hpe11Pair("بین الاقوامی مقابلوں میں ججوں کی سہولت کے لیے ٹیک آف بورڈ کی اگلی طرف 10 سینٹی میٹر چوڑا پلاسٹی سین انڈی کیٹر (Indicator) بورڈ لگا دیا جاتا ہے جس کی سامنے والی اوپری سطح کے پہلے 10 ملی میٹر پر پلاسٹی سین کی تہہ لگادی جاتی ہے۔","In international competitions, for the convenience of the judges, a plasticine indicator (Indicator) board 10 centimetres wide is fixed on the front side of the take-off board, on the first 10 millimetres of whose front upper surface a layer of plasticine is applied.","په نړیوالو سیالیو کې د ججانو د اسانتیا لپاره د ټیک آف بورډ مخکې خوا ته ۱۰ سانتي متره پلن پلاسټیسین انډیکیټر (Indicator) بورډ لګول کېږي چې د مخکې پورتنۍ سطحې په لومړیو ۱۰ ملي مترو د پلاسټیسین ترټه لګول کېږي.",{"id": "hpe11-s090-p4"})
]});
