hpe11AddSection("hpe11-u07",{"id": "hpe11-s104-volleyball-10", "title": "Duties of the line man; volleyball skills: digging (two hands, one hand)", "headingUrdu": "لائن مین کے فرائض؛ والی بال کی مہارتیں: دونوں ہاتھوں اور ایک ہاتھ سے بال اٹھانا", "headingPashto": "د لاین مین دندې؛ د والیبال مهارتونه: په دواړو لاسونو او یو لاس توپ پورته کول", "sourceLanguage": "ur", "source": {"pdfPage": 104, "printedPage": "102"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s104-h1", "hpe11-s104-p2", "hpe11-s104-p3", "hpe11-s104-p4", "hpe11-s104-p5", "hpe11-s104-p6", "hpe11-s104-h7", "hpe11-s104-h8", "hpe11-s104-p9", "hpe11-s104-p10", "hpe11-s104-p11", "hpe11-s104-p12", "hpe11-s104-p13", "hpe11-s104-p14"]}, {"type": "figure", "index": 0}, {"type": "paragraphs", "ids": ["hpe11-s104-h15", "hpe11-s104-p16"]}], "equations": [], "figures": [{"id": "hpe11-s104-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" role=\"img\" aria-label=\"A volleyball player in a blue shirt bending with both arms joined in front, hitting a volleyball low, against a pink wall\" style=\"width:100%;max-width:360px;height:auto;background:#fff\"><rect x=\"0\" y=\"0\" width=\"360\" height=\"90\" fill=\"#f8bbd0\"/><circle cx=\"130\" cy=\"60\" r=\"24\" fill=\"#5d4037\"/><path d=\"M130 84 l-10 60 M118 100 l-60 40 M130 100 l70 30\" stroke=\"#1976d2\" stroke-width=\"22\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"215\" cy=\"140\" r=\"34\" fill=\"#fff\" stroke=\"#1565c0\" stroke-width=\"4\"/><path d=\"M185 130 q30 -20 60 0 M190 150 q25 18 50 0\" stroke=\"#fdd835\" stroke-width=\"5\" fill=\"none\"/></svg>", "caption": "Digging: both hands joined, arms straight, body slightly bent", "captionUrdu": "دونوں ہاتھوں سے بال اٹھانا: ہاتھ ملے ہوئے، بازو سیدھے، جسم قدرے جھکا ہوا", "captionPashto": "په دواړو لاسونو توپ پورته کول: لاسونه یو ځای، لاسونه سیده، بدن یو څه کږ", "labels": [{"en": "Digging", "ur": "دونوں ہاتھوں سے بال اٹھانا", "ps": "په دواړو لاسونو توپ پورته کول"}], "sourceGap": {"note": "Simplified coded redrawing of the coloured illustration of a player doing a dig."}}], "sourceNote": "Printed page 102: duties of the line man (i–v) and the first two volleyball skills (digging with two hands and with one hand). The page number “102” and the footer strip are cropped at the foot of the scan. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:52:38.313977+00:00", "scope": "Scan 104 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("4۔ لائن مین:","4. Line Man:","۴. لاین مین:",{"id": "hpe11-s104-h1", "kind": "heading"}),
hpe11Pair("i۔ لائن مین ہر کونے میں 3 میٹر کے فاصلہ پر فری زون میں کھڑے ہوتے ہیں۔","i. Line men stand in the free zone at a distance of 3 metres in every corner.","i. لاین مینان په هر کونج کې د ۳ مترو په واټن په فري زون کې ولاړ وي.",{"id": "hpe11-s104-p2", "listGroup": "lm"}),
hpe11Pair("ii۔ بال کا کورٹ کے اندر یا باہر گرنے پر جھنڈی سے اشارہ دیتا ہے۔","ii. Signals with the flag when the ball falls inside or outside the court.","ii. کله چې توپ د کورټ دننه یا بهر ولوېږي په بیرغ اشاره کوي.",{"id": "hpe11-s104-p3", "listGroup": "lm"}),
hpe11Pair("iii۔ اپنے نزدیک کی سائیڈ لائن اور اینڈ لائن کی نگرانی کرتا ہے۔","iii. Watches the sideline and end line nearest to him.","iii. خپل نږدې د ساید لاین او اینډ لاین څارنه کوي.",{"id": "hpe11-s104-p4", "listGroup": "lm"}),
hpe11Pair("iv۔ سروس کے دوران کھلاڑی کی غلطی ریفری کو بتاتا ہے۔","iv. Tells the referee the player’s mistake during service.","iv. د سروس په موده کې د لوبغاړي غلطي ریفري ته ورښيي.",{"id": "hpe11-s104-p5", "listGroup": "lm"}),
hpe11Pair("v۔ کنارے ٹچ کرتے ہوئے بال کا اشارہ جھنڈی سے دیتا ہے۔","v. Signals with the flag when the ball touches the edge.","v. کله چې توپ څنډه لمسوي نو په بیرغ اشاره کوي.",{"id": "hpe11-s104-p6", "listGroup": "lm"}),
hpe11Pair("والی بال کی مہارتیں:","Skills of Volleyball:","د والیبال مهارتونه:",{"id": "hpe11-s104-h7", "kind": "heading"}),
hpe11Pair("1۔ دونوں ہاتھوں سے بال اٹھانا (Digging):","1. Lifting the Ball with Both Hands (Digging):","۱. په دواړو لاسونو توپ پورته کول (Digging):",{"id": "hpe11-s104-h8", "kind": "heading"}),
hpe11Pair("دونوں ہاتھوں کی انگلیاں آپس میں ملائیں۔","Join the fingers of both hands together.","د دواړو لاسونو ګوتې یو له بل سره یو ځای کړئ.",{"id": "hpe11-s104-p9", "listGroup": "dg"}),
hpe11Pair("دونوں انگوٹھے ایک سیدھ میں ملے ہوں۔","Both thumbs should be joined in one line.","دواړه غټې ګوتې په یو سیده کې یو ځای وي.",{"id": "hpe11-s104-p10", "listGroup": "dg"}),
hpe11Pair("دونوں ہاتھ ایک مکا کی شکل اختیار کریں گے۔","Both hands will take the form of a fist.","دواړه لاسونه به د یو مټې بڼه اختیاروي.",{"id": "hpe11-s104-p11", "listGroup": "dg"}),
hpe11Pair("بازو بالکل سیدھے ہوں۔","The arms should be perfectly straight.","لاسونه بالکل سیده وي.",{"id": "hpe11-s104-p12", "listGroup": "dg"}),
hpe11Pair("جسم قدرے جھکا ہو۔","The body should be slightly bent.","بدن یو څه کږ وي.",{"id": "hpe11-s104-p13", "listGroup": "dg"}),
hpe11Pair("بال کو نیچے سے اوپر اس طرح ماریں کے دوبارہ بلند ہو جائے۔","Hit the ball from below upward so that it rises again.","توپ له ښکته نه پورته داسې ووهئ چې بیا لوړ شي.",{"id": "hpe11-s104-p14", "listGroup": "dg"}),
hpe11Pair("2۔ ایک ہاتھ سے بال اٹھانا (One hand Digging):","2. Lifting the Ball with One Hand (One hand Digging):","۲. په یو لاس توپ پورته کول (One hand Digging):",{"id": "hpe11-s104-h15", "kind": "heading"}),
hpe11Pair("جب بال پہنچ سے باہر جا رہا ہو اور کمر سے نیچے زمین پر گر رہا ہو تو جس طرف بال گر رہا ہو اسی طرف جسم کو جھکایا جائے بازو کو پھیلاتے ہوئے بال کو زمین پر گرنے سے پہلے اس طرح مارنا کہ بال اوپر اٹھ جائے تاکہ دوسرا کھلاڑی اسے کھیل سکے۔","When the ball is going out of reach and falling on the ground below the waist, the body should be bent towards the side where the ball is falling and, extending the arm, the ball should be hit before it falls on the ground in such a way that the ball rises up, so that another player can play it.","کله چې توپ له رسا بهر ځي او له ملا ښکته په ځمکه لوېږي نو چې کومې خوا ته توپ لوېږي هماغې خوا ته بدن کږ شي لاس غځولو سره توپ په ځمکه د لوېدو نه مخکې داسې وهل چې توپ پورته شي ترڅو بل لوبغاړی هغه ولوبولای شي.",{"id": "hpe11-s104-p16"})
]});
