hpe11AddSection("hpe11-u07",{"id": "hpe11-s105-volleyball-11", "title": "Volleyball skills: service and its four kinds", "headingUrdu": "والی بال کی مہارتیں: سروس کرنا اور اس کے چار طریقے", "headingPashto": "د والیبال مهارتونه: سروس کول او د هغې څلور طریقې", "sourceLanguage": "ur", "source": {"pdfPage": 105, "printedPage": "103"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s105-h1", "hpe11-s105-p2", "hpe11-s105-h3", "hpe11-s105-p4", "hpe11-s105-h5", "hpe11-s105-p6", "hpe11-s105-h7", "hpe11-s105-p8", "hpe11-s105-h9", "hpe11-s105-p10"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s105-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 300 420\" role=\"img\" aria-label=\"Four small illustrations of volleyball serves stacked vertically: underhand serve (top), overhead serve, round serve and a jump serve (bottom), each with a player and ball\" style=\"width:100%;max-width:300px;height:auto;background:#fff\"><g><circle cx=\"130\" cy=\"50\" r=\"14\" fill=\"#6d4c41\"/><path d=\"M130 64 l-6 50 M130 74 l-30 18 M130 74 l34 20 M124 114 l-14 40 M124 114 l18 38\" stroke=\"#e53935\" stroke-width=\"10\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"190\" cy=\"110\" r=\"18\" fill=\"#fff\" stroke=\"#c62828\" stroke-width=\"3\"/></g><g><circle cx=\"120\" cy=\"150\" r=\"14\" fill=\"#6d4c41\"/><path d=\"M120 164 l-6 50 M120 174 l-30 18 M120 174 l34 20 M114 214 l-14 40 M114 214 l18 38\" stroke=\"#ef9a9a\" stroke-width=\"10\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"100\" cy=\"160\" r=\"20\" fill=\"#fff\" stroke=\"#555\" stroke-width=\"3\"/></g><g><circle cx=\"120\" cy=\"260\" r=\"14\" fill=\"#6d4c41\"/><path d=\"M120 274 l-6 50 M120 284 l-30 18 M120 284 l34 20 M114 324 l-14 40 M114 324 l18 38\" stroke=\"#333\" stroke-width=\"10\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"190\" cy=\"270\" r=\"20\" fill=\"#fff\" stroke=\"#555\" stroke-width=\"3\"/></g><g><circle cx=\"180\" cy=\"340\" r=\"14\" fill=\"#6d4c41\"/><path d=\"M180 354 l0 36 M180 362 l-24 -16\" stroke=\"#e53935\" stroke-width=\"9\" fill=\"none\"/><circle cx=\"160\" cy=\"322\" r=\"14\" fill=\"#fff\" stroke=\"#555\" stroke-width=\"3\"/></g></svg>", "caption": "Four kinds of service: underhand, overhead (tennis), round and jump (spike) service", "captionUrdu": "سروس کے چار طریقے: انڈر ہینڈ، اوور ہیڈ (ٹینس)، راؤنڈ اور جمپ (سپائیک) سروس", "captionPashto": "د سروس څلور طریقې: انډر هینډ، اوور هیډ (ټینس)، راونډ او جمپ (سپایک) سروس", "labels": [{"en": "Under hand Service", "ur": "انڈر ہینڈ سروس", "ps": "انډر هینډ سروس"}, {"en": "Over head/Tennis Service", "ur": "اوور ہیڈ / ٹینس سروس", "ps": "اوور هیډ / ټینس سروس"}, {"en": "Round Service", "ur": "راؤنڈ سروس", "ps": "راونډ سروس"}, {"en": "Spike Service", "ur": "جمپ سروس", "ps": "جمپ سروس"}], "sourceGap": {"note": "Simplified coded schematic of the four vertical coloured illustrations; the original pictures are not reproduced."}}], "sourceNote": "Printed page 103: the skill of serving and its four kinds (underhand, overhead/tennis, round, jump/spike) with four illustrations running down the left margin. The page number “103” and the footer strip are cropped at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:52:39.196992+00:00", "scope": "Scan 105 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("3۔ سروس کرنا:","3. Serving:","۳. سروس کول:",{"id": "hpe11-s105-h1", "kind": "heading"}),
hpe11Pair("سروس کے 4 طریقے ہیں اور ہر ایک کی الگ مہارت ہے۔","There are 4 methods of service and each has its separate skill.","د سروس ۴ طریقې دي او د هرې جلا مهارت دی.",{"id": "hpe11-s105-p2"}),
hpe11Pair("(الف) انڈر ہینڈ سروس (Under hand Service):","(a) Underhand Service (Under hand Service):","(الف) انډر هینډ سروس (Under hand Service):",{"id": "hpe11-s105-h3", "kind": "heading"}),
hpe11Pair("کھلاڑی کا منہ نیٹ کی طرف ہوگا۔ پاؤں چلنے کی حالت میں ہوں گے ایک ہاتھ پر بال ہوگا دوسرا فری ہوگا۔ بال کو اوپر کی طرف اچھال کر نیچے سے اوپر کی طرف اس طرح مارنا کہ بال نیٹ کو عبور کر جائے۔","The player’s face will be towards the net. The feet will be as in walking; the ball will be on one hand and the other will be free. Toss the ball upward and hit it from below upward in such a way that the ball crosses the net.","د لوبغاړي مخ به جال لوري ته وي. پښې به د تګ په حالت کې وي په یو لاس به توپ وي او بل به آزاد وي. توپ پورته لوري ته غورځولو سره له ښکته نه پورته لوري ته داسې وهل چې توپ جال تېر کړي.",{"id": "hpe11-s105-p4"}),
hpe11Pair("(ب) اوور ہیڈ یا ٹینس سروس (Over head/Tennis Service):","(b) Overhead or Tennis Service (Over head/Tennis Service):","(ب) اوور هیډ یا ټینس سروس (Over head/Tennis Service):",{"id": "hpe11-s105-h5", "kind": "heading"}),
hpe11Pair("کھلاڑی کے کھڑا ہونے کی پوزیشن انڈر ہینڈ سروس کی طرح ہوگی بال کو ہوا میں اچھال کر خالی ہاتھ اوپر سے مار کر بال کو نیٹ سے دوسری جانب پھینکنا۔","The player’s standing position will be like that of the underhand service; tossing the ball in the air and hitting with the free hand from above, throw the ball to the other side of the net.","د لوبغاړي د ولاړېدو موقعیت به د انډر هینډ سروس په څېر وي توپ په هوا کې غورځولو او په آزاد لاس له پورته وهلو سره توپ د جال بلې خوا ته غورځول.",{"id": "hpe11-s105-p6"}),
hpe11Pair("(ج) راؤنڈ سروس (Round Service):","(c) Round Service (Round Service):","(ج) راونډ سروس (Round Service):",{"id": "hpe11-s105-h7", "kind": "heading"}),
hpe11Pair("اس میں کھلاڑی کا کندھا نیٹ کی طرف ہوگا اور پاؤں سائیڈ لائن کے متوازی ہوں گے بال کو ہوا میں اچھالے۔ گھٹنوں کو تھوڑا سا خم دے کر خالی ہاتھ کو سر کے اوپر سے گھما کر بال کو اس طرح مارے کہ بال نیٹ عبور کر جائے اور مخالف کورٹ میں گرے۔","In this the player’s shoulder will be towards the net and the feet will be parallel to the sideline; he tosses the ball in the air. Bending the knees a little and swinging the free hand from above the head, he hits the ball in such a way that the ball crosses the net and falls in the opponent’s court.","پدې کې د لوبغاړي اوږه به جال لوري ته وي او پښې به د ساید لاین سره موازي وي توپ په هوا کې غورځوي. زنګنونه یو څه کږولو سره آزاد لاس د سر پورته نه ګرځولو سره توپ داسې وهي چې توپ جال تېر کړي او د مخالف په کورټ کې ولوېږي.",{"id": "hpe11-s105-p8"}),
hpe11Pair("(د) جمپ سروس (Spike Service):","(d) Jump Service (Spike Service):","(د) جمپ سروس (Spike Service):",{"id": "hpe11-s105-h9", "kind": "heading"}),
hpe11Pair("کھلاڑی سروس ایریا کے پیچھے سے چند قدم لے گا منہ نیٹ کی جانب ہوگا۔ بال کو ہوا میں اچھالے گا اور ہوا میں جمپ کرتے ہوئے خالی ہاتھ سے اوپر سے اس طرح مارے گا جیسے سپائیک (Spike) کیا جاتا ہے۔","The player will take a few steps from behind the service area, with his face towards the net. He will toss the ball in the air and, jumping in the air, hit it with the free hand from above as a spike (Spike) is done.","لوبغاړی به د سروس ایریا له شا څو ګامونه اخلي مخ به یې جال لوري ته وي. توپ به په هوا کې غورځوي او په هوا کې ټوپ وهلو سره به په آزاد لاس له پورته داسې وهي لکه سپایک (Spike) چې کېږي.",{"id": "hpe11-s105-p10"})
]});
