hpe11AddSection("hpe11-u07",{"id": "hpe11-s107-volleyball-13", "title": "Volleyball skills: passing/setting (boosting)", "headingUrdu": "والی بال کی مہارتیں: پاس بنانا (سیٹنگ / بوسٹنگ)", "headingPashto": "د والیبال مهارتونه: پاس جوړول (سیټنګ / بوسټنګ)", "sourceLanguage": "ur", "source": {"pdfPage": 107, "printedPage": "105"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s107-h1", "hpe11-s107-p2"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s107-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 260\" role=\"img\" aria-label=\"Two panels of a volleyball player in a red shirt setting the ball above the head with both hands, with red arrows showing the upward direction of the ball and a forward arrow\" style=\"width:100%;max-width:520px;height:auto;background:#fff\"><g><circle cx=\"130\" cy=\"130\" r=\"22\" fill=\"#6d4c41\"/><path d=\"M130 152 l0 80 M130 170 l-40 -50 M130 170 l50 -50\" stroke=\"#e53935\" stroke-width=\"26\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"130\" cy=\"50\" r=\"30\" fill=\"#1a237e\"/><path d=\"M110 46 q20 -10 40 0\" stroke=\"#ffb74d\" stroke-width=\"6\" fill=\"none\"/><circle cx=\"390\" cy=\"150\" r=\"22\" fill=\"#6d4c41\"/><path d=\"M390 172 l0 80 M390 190 l-40 -50 M390 190 l50 -50\" stroke=\"#e53935\" stroke-width=\"26\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"390\" cy=\"70\" r=\"30\" fill=\"#1a237e\"/><path d=\"M370 66 q20 -10 40 0\" stroke=\"#ffb74d\" stroke-width=\"6\" fill=\"none\"/><path d=\"M170 86 l10 -26 M420 40 l-8 20 M500 110 l-22 8\" stroke=\"#e53935\" stroke-width=\"4\" fill=\"none\"/></g></svg>", "caption": "Setting/boosting: the ball passed above the head with both hands", "captionUrdu": "پاس بنانا: دونوں ہاتھوں سے بال کو سر کے اوپر پاس کرنا", "captionPashto": "پاس جوړول: په دواړو لاسونو توپ د سر پورته پاس کول", "labels": [{"en": "Setting/Boosting", "ur": "پاس بنانا", "ps": "پاس جوړول"}], "sourceGap": {"note": "Simplified coded redrawing of the two coloured illustrations of setting."}}], "sourceNote": "Printed page 105: the sixth volleyball skill (setting/boosting) with two illustrations. The page number “105” and the footer strip are partly cropped at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:53:55.382305+00:00", "scope": "Scan 107 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("6۔ پاس بنانا (Setting/Boosting):","6. Making the Pass (Setting/Boosting):","۶. پاس جوړول (Setting/Boosting):",{"id": "hpe11-s107-h1", "kind": "heading"}),
hpe11Pair("جب دفاعی کھلاڑی بال کو اوپر اچھالے تو بوسٹر (Booster) دونوں ہاتھوں سے بال کو نیٹ کے اوپر اس طرح اچھالے کہ اس ٹیم کا دوسرا کھلاڑی جمپ کر کے بال کو مخالف کورٹ میں سمیش کر سکے۔ بوسٹر کبھی سامنے والے کبھی پیچھے والے کھلاڑی کی طرف بال اس طرح اچھالے کہ بلاکنگ کا موقع ہی نہ مل سکے۔ بوسٹر بال کو آئیڈیا بھی کر سکتا ہے یعنی خود ہی آہستہ سے بال کو مخالف کی طرف ڈاج دیتے ہوئے پھینک دے۔","When the defensive player tosses the ball up, the booster (Booster) with both hands should toss the ball over the net in such a way that another player of that team can jump and smash the ball into the opponent’s court. The booster should sometimes toss the ball towards the player in front, sometimes towards the one behind, in such a way that there is no opportunity of blocking at all. The booster can also use an idea (“Idea” as printed), that is, himself dodging, gently throw the ball towards the opponent.","کله چې دفاعي لوبغاړی توپ پورته غورځوي نو بوسټر (Booster) په دواړو لاسونو توپ د جال پورته داسې غورځوي چې د هغه ټیم بل لوبغاړی ټوپ وهلو سره توپ د مخالف په کورټ کې سمېش کړای شي. بوسټر کله مخکې والا او کله شاته والا لوبغاړي لوري ته توپ داسې غورځوي چې د بلاکنګ موقع ورته ونه مومي. بوسټر توپ ته آیډیا هم کولای شي یعنې پخپله ورو توپ د مخالف لوري ته ډاج ورکولو سره وغورځوي.",{"id": "hpe11-s107-p2", "sourceGap": {"note": "The scan prints “آئیڈیا” (idea) for the tactic of a gentle drop shot; kept as printed."}})
]});
