hpe11AddSection("hpe11-u07",{"id": "hpe11-s113-tabletennis-4", "title": "Table tennis: skills — grip, forehand, backhand, serve (forehand, backhand)", "headingUrdu": "ٹیبل ٹینس کی مہارتیں: گرفت، سیدھے ہاتھ سے، الٹے ہاتھ سے، سروس", "headingPashto": "د ټیبل ټینس مهارتونه: نیونه، په ښي لاس، په کیڼ لاس، سروس", "sourceLanguage": "ur", "source": {"pdfPage": 113, "printedPage": "111"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s113-h1", "hpe11-s113-h2", "hpe11-s113-p3", "hpe11-s113-h4", "hpe11-s113-p5", "hpe11-s113-h6", "hpe11-s113-p7", "hpe11-s113-h8", "hpe11-s113-p9", "hpe11-s113-h10", "hpe11-s113-p11", "hpe11-s113-h12", "hpe11-s113-p13"]}], "equations": [], "sourceNote": "Printed page 111: skills of table tennis — grip, forehand, backhand, service (forehand and backhand). The footer strip is partly cropped. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T02:55:24.481178+00:00", "scope": "Scan 113 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("ٹیبل ٹینس کی مہارتیں (Skills)","Skills of Table Tennis (Skills)","د ټیبل ټینس مهارتونه (Skills)",{"id": "hpe11-s113-h1", "kind": "heading"}),
hpe11Pair("گرفت:","Grip:","نیونه:",{"id": "hpe11-s113-h2", "kind": "heading"}),
hpe11Pair("ریکٹ کو اس طرح پکڑا جائے کہ شہادت کی انگلی سہارا دے۔ انگوٹھا اور باقی انگلیاں دستے کو پکڑیں اس طرح دونوں جانب ضرب لگانے میں آسانی ہوتی ہے۔","The racket should be held in such a way that the index finger gives support. The thumb and the remaining fingers hold the handle; in this way it is easy to hit on both sides.","ریکټ داسې ونیول شي چې د شهادت ګوته سهارا ورکړي. غټه ګوته او پاتې ګوتې دسته ونیسي په دې ډول په دواړو لورو ګوزار وهلو کې اسانتیا وي.",{"id": "hpe11-s113-p3"}),
hpe11Pair("سیدھے ہاتھ سے:","With the Right Hand (Forehand):","په ښي لاس:",{"id": "hpe11-s113-h4", "kind": "heading"}),
hpe11Pair("پہلو کے رخ کھڑے ہوں۔ ریکٹ پر شہادت کی انگلی سیدھی رکھیں اور خالی ہاتھ کی طرف والا پاؤں میز کے نزدیک رکھیں۔","Stand sideways. Keep the index finger straight on the racket, and keep the foot on the side of the free hand near the table.","څنګ لوري ولاړ اوسئ. په ریکټ د شهادت ګوته سیده وساتئ او د آزاد لاس لوري پښه د میز سره نږدې وساتئ.",{"id": "hpe11-s113-p5"}),
hpe11Pair("الٹے ہاتھ سے:","With the Back Hand (Backhand):","په کیڼ لاس:",{"id": "hpe11-s113-h6", "kind": "heading"}),
hpe11Pair("رخ ترچھا رکھیں جس ہاتھ میں ریکٹ ہو وہ پاؤں آگے رکھیں جسم آگے اور گھٹنے قدرے جھکے ہوں۔","Keep the angle slanted; put forward the foot of the hand holding the racket; the body forward and the knees slightly bent.","لوری کوږ وساتئ په کوم لاس کې چې ریکټ وي هغه پښه مخکې وساتئ بدن مخکې او زنګنونه یو څه کږ وي.",{"id": "hpe11-s113-p7"}),
hpe11Pair("سروس:","Service:","سروس:",{"id": "hpe11-s113-h8", "kind": "heading"}),
hpe11Pair("سروس کرتے وقت مخالف کی پوزیشن کو مدِ نظر رکھیں۔ بال کو ہوا میں اچھالیں اور اس طرح ضرب لگائیں کہ بال پہلے اپنے حصہ پر لگے پھر نیٹ عبور کر کے مخالف کے حصہ میں لگے اس کی درج ذیل مہارتیں ہیں۔","While serving keep the position of the opponent in view. Toss the ball in the air and hit it in such a way that the ball first touches one’s own part and then, crossing the net, touches the opponent’s part. Its skills are as follows.","د سروس کولو په وخت د مخالف موقعیت په پام کې ولرئ. توپ په هوا کې وغورځوئ او داسې ګوزار ووهئ چې توپ لومړی خپلې برخې ته ولګېږي بیا جال تېر کړي او د مخالف برخې ته ولګېږي د هغې مهارتونه لاندې دي.",{"id": "hpe11-s113-p9"}),
hpe11Pair("فور ہینڈ سروس:","Forehand Service:","فورهینډ سروس:",{"id": "hpe11-s113-h10", "kind": "heading"}),
hpe11Pair("جسم کا جھکاؤ آگے کی طرف ہو ریکٹ نیچے اور پیچھے رہے جو نہی بال ہوا میں جائے ریکٹ کو آگے اور اوپر لائیں اور اس طرح ضرب لگائیں کہ بال گھومتے ہوئے مخالف کے حصہ میں لگے۔","The body should lean forward, the racket stays down and behind; as soon as the ball goes into the air bring the racket forward and up and hit in such a way that the ball, spinning, strikes the opponent’s part.","د بدن کږوالی مخکې لوري ته وي ریکټ ښکته او شاته پاتې شي همدا چې توپ هوا ته ځي ریکټ مخکې او پورته راوړئ او داسې ګوزار ووهئ چې توپ ګرځېدو سره د مخالف برخې ته ولګېږي.",{"id": "hpe11-s113-p11"}),
hpe11Pair("بیک ہینڈ سروس:","Backhand Service:","بیک هینډ سروس:",{"id": "hpe11-s113-h12", "kind": "heading"}),
hpe11Pair("اس میں بھی جسم کا انداز بیک ہینڈ کی طرح ہوتا ہے بال جب آئے تو الٹے ہاتھ سے اس طرح ضرب لگائیں کہ بال مخالف کے حصہ میں لگے۔","In this too the body’s posture is like the backhand; when the ball comes, hit with the back hand in such a way that the ball strikes the opponent’s part.","پدې کې هم د بدن انداز د بیک هینډ په څېر وي کله چې توپ راشي نو په کیڼ لاس داسې ګوزار ووهئ چې توپ د مخالف برخې ته ولګېږي.",{"id": "hpe11-s113-p13"})
]});
