hpe11AddSection("hpe11-u07",{"id": "hpe11-s128-kabaddi-2", "title": "Kabaddi: players, time, rules (1)", "headingUrdu": "کبڈی: کھلاڑی، کھیل کا وقت، قواعد و ضوابط", "headingPashto": "کبډي: لوبغاړي، د لوبې وخت، قواعد او ضوابط", "sourceLanguage": "ur", "source": {"pdfPage": 128, "printedPage": "126"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s128-h1", "hpe11-s128-p2", "hpe11-s128-h3", "hpe11-s128-p4", "hpe11-s128-h5", "hpe11-s128-p6", "hpe11-s128-p7", "hpe11-s128-p8", "hpe11-s128-p9", "hpe11-s128-p10", "hpe11-s128-p11", "hpe11-s128-p12", "hpe11-s128-p13", "hpe11-s128-p14", "hpe11-s128-p15", "hpe11-s128-p16"]}], "equations": [], "sourceNote": "Printed page 126: players, duration, and the first part of the rules and regulations of Kabaddi (stars list). The word “جاپھی” (stopper) is kept as printed. The page number “126” is shown in a hexagon at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T03:01:04.292175+00:00", "scope": "Scan 128 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("کھلاڑی:","Players:","لوبغاړي:",{"id": "hpe11-s128-h1", "kind": "heading"}),
hpe11Pair("ایک ٹیم میں 11 کھلاڑی ہوں گے اس کے علاوہ دو متبادل کھلاڑی۔","There will be 11 players in a team, besides two substitute players.","په یوه ټیم کې ۱۱ لوبغاړي وي د دې ترڅنګ دوه بدل لوبغاړي.",{"id": "hpe11-s128-p2"}),
hpe11Pair("کھیل کا وقت:","Time of the Game:","د لوبې وخت:",{"id": "hpe11-s128-h3", "kind": "heading"}),
hpe11Pair("20-20 منٹ کے دو ہاف ہوں گے۔ دونوں ہاف میں 5 منٹ کا وقفہ ہوتا ہے اور کھلاڑی اطراف بدلتے ہیں۔","There will be two halves of 20-20 minutes. There is a 5-minute break between the two halves and the players change sides.","د ۲۰–۲۰ دقیقو دوه نیمایۍ وي. په دواړو نیمایو کې د ۵ دقیقو وقفه وي او لوبغاړي اړخونه بدلوي.",{"id": "hpe11-s128-p4"}),
hpe11Pair("قواعد و ضوابط:","Rules and Regulations:","قواعد او ضوابط:",{"id": "hpe11-s128-h5", "kind": "heading"}),
hpe11Pair("کھیل کا آغاز ٹاس سے ہوتا ہے۔ جیتنے والے کو اختیار ہے کہ وہ سائیڈ لے یا پہلے حملہ آور کو بھیجے۔","The game begins with a toss. The winner has the choice to take a side or to send the raider first.","لوبه په ټاس پیلېږي. ګټونکي ته اختیار وي چې اړخ واخلي یا لومړی برید کوونکی ولېږي.",{"id": "hpe11-s128-p6", "listGroup": "kr1"}),
hpe11Pair("دونوں ٹیمیں باری باری اپنا ایک کھلاڑی کبڈی ڈالنے (حملہ) کے لیے بھیجتی ہیں۔","Both teams in turn send one of their players to raid (attack).","دواړه ټیمونه په بدل بدل خپل یو لوبغاړی د کبډۍ اچولو (برید) لپاره لېږي.",{"id": "hpe11-s128-p7", "listGroup": "kr1"}),
hpe11Pair("ایک کھلاڑی لگاتار دو مرتبہ کبڈی (حملہ) نہیں ڈال سکتا۔","A player cannot raid (attack) twice in a row.","یو لوبغاړی په پرله پسې ډول دوه ځله کبډۍ (برید) نشي اچولی.",{"id": "hpe11-s128-p8", "listGroup": "kr1"}),
hpe11Pair("حملہ آور مخالف کے حصے میں 30 سیکنڈ تک ٹھہر سکتا ہے۔ 30 سیکنڈ میں اس نے مخالف کھلاڑی کو چھو کر واپس آنا ہوگا۔ ناکامی کی صورت میں مخالف کو ایک پوائنٹ ملے گا۔","The raider can stay in the opponent’s half for up to 30 seconds. Within 30 seconds he must touch an opposing player and return. In case of failure the opponent gets one point.","برید کوونکی د مخالف په برخه کې تر ۳۰ ثانیو پورې پاتې کېدای شي. په ۳۰ ثانیو کې به یې مخالف لوبغاړی لمس کړی او بېرته راځي. په ناکامۍ کې به مخالف ته یو پوائنټ ورکول کېږي.",{"id": "hpe11-s128-p9", "listGroup": "kr1"}),
hpe11Pair("اگر کامیابی سے 30 سیکنڈ میں اپنے کورٹ میں واپس داخل ہوا تو حملہ آور کو پوائنٹ ملے گا۔","If he successfully re-enters his own court within 30 seconds, the raider gets a point.","که په بریالیتوب په ۳۰ ثانیو کې خپل کورټ ته بېرته داخل شو نو برید کوونکي ته پوائنټ ورکول کېږي.",{"id": "hpe11-s128-p10", "listGroup": "kr1"}),
hpe11Pair("دفاعی ٹیم اگر حملہ آور کو 30 سیکنڈ تک اپنے کورٹ میں پکڑے رکھے یا روکے رکھے تو اسے ایک پوائنٹ ملتا ہے۔","If the defending team holds or keeps the raider in its court for 30 seconds, it gets one point.","که دفاعي ټیم برید کوونکی تر ۳۰ ثانیو پورې په خپل کورټ کې ونیسي یا ودرو، نو یو پوائنټ ورکول کېږي.",{"id": "hpe11-s128-p11", "listGroup": "kr1"}),
hpe11Pair("جس کھلاڑی کا ہاتھ حملہ آور کو ٹچ ہو یا حملہ آور خود جسے ٹچ کرے وہی کھلاڑی اسے پکڑ سکتا ہے۔ اگر دوسرا کوئی چھوٹے تو پوائنٹ حملہ آور کو ملتا ہے۔","The player whose hand touches the raider, or whom the raider himself touches, is the only one who can catch him. If any other touches, the point goes to the raider.","هغه لوبغاړی چې لاس یې برید کوونکي ته ولګي یا برید کوونکی پخپله چې هغه ولمسوي، همدا لوبغاړی یې نیولی شي. که بل څوک ولمسوي نو پوائنټ برید کوونکي ته ورکول کېږي.",{"id": "hpe11-s128-p12", "listGroup": "kr1"}),
hpe11Pair("اگر ایک سے زیادہ کھلاڑی حملہ آور کو چھو لیں تو پوائنٹ حملہ آور کو دیا جاتا ہے۔","If more than one player touches the raider, the point is given to the raider.","که له یوه ډېر لوبغاړي برید کوونکی ولمسوي نو پوائنټ برید کوونکي ته ورکول کېږي.",{"id": "hpe11-s128-p13", "listGroup": "kr1"}),
hpe11Pair("اگر کوئی حملہ آور پکڑا جائے تو امپائر اُس وقت تک وِسل نہیں کرے گا جب تک وہ خود ہاتھ نہ اٹھائے یا 30 سیکنڈ گزر نہ جائیں۔","If a raider is caught, the umpire will not whistle until he himself raises his hand or 30 seconds have passed.","که کوم برید کوونکی ونیول شي نو امپایر به تر هغه وخته سیټۍ نه وهي ترڅو چې هغه پخپله لاس پورته نه کړي یا ۳۰ ثانیې تېرې نه شي.",{"id": "hpe11-s128-p14", "listGroup": "kr1"}),
hpe11Pair("حملہ آور کو گراؤنڈ سے باہر دھکیل دیا جائے تو پوائنٹ دفاعی ٹیم کو ملے گا اور اگر دفاعی ٹیم کا کھلاڑی دائرہ سے باہر نکل جائے تو پوائنٹ حملہ آور ٹیم کو ملے گا۔","If the raider is pushed outside the ground, the point will go to the defending team; and if a player of the defending team goes outside the circle, the point will go to the raiding team.","که برید کوونکی له ګراونډ نه بهر وټیل شي نو پوائنټ دفاعي ټیم ته ورکول کېږي او که د دفاعي ټیم لوبغاړی له دایرې بهر ووځي نو پوائنټ د برید کوونکي ټیم ته ورکول کېږي.",{"id": "hpe11-s128-p15", "listGroup": "kr1"}),
hpe11Pair("پانچ کھلاڑی بطور جاپھی (دفاعی) موجود نہ ہوں تو پوائنٹ حملہ آور کو دیا جائے گا۔","If five players are not present as stoppers (defenders), the point will be given to the raider.","که پنځه لوبغاړي د جاپهي (دفاعي) په توګه موجود نه وي نو پوائنټ برید کوونکي ته ورکول کېږي.",{"id": "hpe11-s128-p16", "listGroup": "kr1"})
]});
// END HPE SOURCE SCAN 128

