hpe11AddSection("hpe11-u07",{"id": "hpe11-s136-hockey-4", "title": "Hockey: dress and equipment; start of play; free hit; corner; penalty corner (start)", "headingUrdu": "ہاکی: لباس اور سامان؛ کھیل کا آغاز؛ فری ہٹ؛ کارنر؛ پنلٹی کارنر", "headingPashto": "هاکي: جامې او سامان؛ د لوبې پیل؛ فري هټ؛ کارنر؛ پنلټي کارنر", "sourceLanguage": "ur", "source": {"pdfPage": 136, "printedPage": "134"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s136-h1", "hpe11-s136-p2", "hpe11-s136-h3", "hpe11-s136-p4", "hpe11-s136-h5", "hpe11-s136-p6", "hpe11-s136-p7", "hpe11-s136-p8", "hpe11-s136-p9", "hpe11-s136-h10", "hpe11-s136-p11", "hpe11-s136-h12", "hpe11-s136-p13"]}], "equations": [], "sourceNote": "Printed page 134: dress and equipment, start of the game, free hit (A–D), corner, and the introduction to penalty corner. The page number “134” is shown in a hexagon at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T03:04:09.544904+00:00", "scope": "Scan 136 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("لباس اور سامان","Dress and Equipment","جامې او سامان",{"id": "hpe11-s136-h1", "kind": "heading"}),
hpe11Pair("ہر ٹیم اپنے مخصوص رنگ میں ہوتی ہے۔ ایک ٹیم کے تمام کھلاڑیوں کا لباس ایک جیسا ہوتا ہے۔ دونوں ٹیموں کا لباس مختلف ہوتا ہے۔ گول کیپر کے لباس کا رنگ اپنی ٹیم سے مختلف ہوتا ہے۔ صرف گول کیپر، ماسک، گلوز پیڈ وغیرہ پہن سکتا ہے۔","Each team is in its own particular colour. All the players of one team have the same dress. The dress of the two teams is different. The colour of the goalkeeper’s dress is different from his own team. Only the goalkeeper can wear a mask, gloves, pads and so on.","هره ټیم په خپل ځانګړي رنګ کې وي. د یو ټیم د ټولو لوبغاړو جامې یو شان وي. د دواړو ټیمونو جامې توپیر لري. د ګول کیپر د جامو رنګ له خپل ټیم نه توپیر لري. یوازې ګول کیپر ماسک، دستکشې، پیډ او داسې نور اغوستلی شي.",{"id": "hpe11-s136-p2"}),
hpe11Pair("کھیل کا آغاز","Start of the Game","د لوبې پیل",{"id": "hpe11-s136-h3", "kind": "heading"}),
hpe11Pair("جو ٹیم ٹاس جیت جاتی ہے وہ سائیڈ لیتی ہے یا پاس کرتی ہے۔ کھیل شروع کرتے وقت، وقفہ کے بعد اور گول ہونے کے بعد کھیل پاس سے شروع ہوتا ہے۔","The team that wins the toss takes the side or makes the pass. At the start of the game, after the break and after a goal, the game starts with a pass.","هغه ټیم چې ټاس وګټي اړخ اخلي یا پاس کوي. د لوبې د پیل پر مهال، له وقفې وروسته او له ګول وروسته لوبه په پاس پیلېږي.",{"id": "hpe11-s136-p4"}),
hpe11Pair("فری ہٹ","Free Hit","فري هټ",{"id": "hpe11-s136-h5", "kind": "heading"}),
hpe11Pair("ا۔ جس جگہ فاؤل ہوگا وہاں سے فری ہٹ لی جاتی ہے۔","A. The free hit is taken from the place where the foul occurs.","ا. چېرته چې فاول وي له هماغه ځایه فري هټ اخیستل کېږي.",{"id": "hpe11-s136-p6", "listGroup": "fh"}),
hpe11Pair("ب۔ فری ہٹ لگاتے وقت بال ساکن ہو۔","B. The ball should be stationary when taking the free hit.","ب. د فري هټ د وهلو پر مهال توپ ساکن وي.",{"id": "hpe11-s136-p7", "listGroup": "fh"}),
hpe11Pair("ج۔ فری ہٹ کے وقت مخالف کھلاڑی 5 گز کے فاصلے پر ہوتے ہیں۔","C. At the time of the free hit the opposing players are at a distance of 5 yards.","ج. د فري هټ پر مهال مخالف لوبغاړي د ۵ ګزو په واټن وي.",{"id": "hpe11-s136-p8", "listGroup": "fh"}),
hpe11Pair("د۔ جو کھلاڑی فری ہٹ لگائے گا۔ وہ دوبارہ بال کو اس وقت تک نہیں کھیل سکتا جب تک کوئی دوسرا کھلاڑی بال کو ٹچ نہ کرے۔","D. The player who takes the free hit cannot play the ball again until another player touches the ball.","د. هغه لوبغاړی چې فري هټ وهي بیا توپ نشي لوبولی تر هغه چې بل لوبغاړی توپ ونه لمسوي.",{"id": "hpe11-s136-p9", "listGroup": "fh"}),
hpe11Pair("کارنر","Corner","کارنر",{"id": "hpe11-s136-h10", "kind": "heading"}),
hpe11Pair("دفاعی ٹیم کے کسی کھلاڑی کی ہاکی سے بال 25 گز کے اندر ٹچ ہو کر گول لائن عبور کر جائے تو حملہ آور ٹیم کو کارنر دیا جائے گا۔ کارنر کے وقت کھلاڑی جہاں چاہیں کھڑے ہو سکتے ہیں۔ کارنر کی ہٹ سے براہ راست گول نہیں ہو سکتا۔","If the ball, touched by the hockey stick of a player of the defending team within 25 yards, crosses the goal line, a corner will be given to the attacking team. At the time of the corner the players can stand wherever they like. A goal cannot be scored directly from the corner hit.","که د دفاعي ټیم د کوم لوبغاړي له هاکۍ سره توپ په ۲۵ ګزو دننه لمس شي او د ګول لاین تېر شي نو برید کوونکي ټیم ته کارنر ورکول کېږي. د کارنر پر مهال لوبغاړي چېرته چې وغواړي ودرېدای شي. د کارنر له هټ نه مستقیم ګول نشي کېدای.",{"id": "hpe11-s136-p11"}),
hpe11Pair("پنلٹی کارنر","Penalty Corner","پنلټي کارنر",{"id": "hpe11-s136-h12", "kind": "heading"}),
hpe11Pair("کسی بھی ٹیم کو پنلٹی کارنر مندرجہ ذیل صورتوں میں دیا جاتا ہے۔","A penalty corner is given to any team in the following cases.","هر ټیم ته پنلټي کارنر په لاندې صورتونو کې ورکول کېږي.",{"id": "hpe11-s136-p13", "sourceGap": {"note": "The list of cases continues on the next page (printed page 135)."}})
]});
