hpe11AddSection("hpe11-u07",{"id": "hpe11-s137-hockey-5", "title": "Hockey: penalty corner cases (1–8); goalkeeper photograph", "headingUrdu": "ہاکی: پنلٹی کارنر کی صورتیں (1–8)", "headingPashto": "هاکي: د پنلټي کارنر صورتونه (۱–۸)", "sourceLanguage": "ur", "source": {"pdfPage": 137, "printedPage": "135"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s137-p1", "hpe11-s137-p2", "hpe11-s137-p3", "hpe11-s137-p4", "hpe11-s137-p5", "hpe11-s137-p6", "hpe11-s137-p7", "hpe11-s137-p8"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s137-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 260\" role=\"img\" aria-label=\"A goal with a green “Rio 2016” banner behind it: a goalkeeper in an orange shirt, pads and mask stands in the goal, with defenders in white shirts and one player in blue in front\" style=\"width:100%;max-width:420px;height:auto;background:#fff\"><rect width=\"420\" height=\"260\" fill=\"#6ec04a\"/><rect x=\"40\" y=\"30\" width=\"340\" height=\"190\" fill=\"none\" stroke=\"#fff\" stroke-width=\"6\"/><text x=\"210\" y=\"120\" font-size=\"56\" text-anchor=\"middle\" fill=\"#e8f5e9\" font-family=\"sans-serif\" font-weight=\"bold\">Rio 2016</text><circle cx=\"210\" cy=\"95\" r=\"14\" fill=\"#fff\"/><rect x=\"190\" y=\"110\" width=\"40\" height=\"70\" rx=\"10\" fill=\"#fb8c00\"/><rect x=\"192\" y=\"180\" width=\"36\" height=\"40\" fill=\"#212121\"/><g fill=\"#eceff1\"><circle cx=\"120\" cy=\"140\" r=\"11\"/><rect x=\"108\" y=\"152\" width=\"24\" height=\"55\" rx=\"8\"/><circle cx=\"300\" cy=\"145\" r=\"11\"/><rect x=\"288\" y=\"157\" width=\"24\" height=\"55\" rx=\"8\"/><circle cx=\"345\" cy=\"135\" r=\"11\"/><rect x=\"333\" y=\"147\" width=\"24\" height=\"55\" rx=\"8\"/></g><circle cx=\"65\" cy=\"175\" r=\"11\" fill=\"#1976d2\"/><rect x=\"53\" y=\"187\" width=\"24\" height=\"55\" rx=\"8\" fill=\"#1976d2\"/></svg>", "caption": "Defenders and the goalkeeper in front of the goal at a penalty corner", "captionUrdu": "پنلٹی کارنر کے وقت گول کے سامنے دفاعی کھلاڑی اور گول کیپر", "captionPashto": "د پنلټي کارنر پر مهال د ګول مخې ته دفاعي لوبغاړي او ګول کیپر", "labels": [], "sourceGap": {"note": "The original is a coloured photograph; replaced by a simplified coded SVG schematic (no raster image)."}}], "sourceNote": "Printed page 135: eight cases and rules for the penalty corner, with a photograph (goalkeeper and defenders in front of the goal, “Rio 2016” banner) at the foot. Item 8 notes that the rule changes from time to time. The page number “135” is shown in a hexagon at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T03:04:10.131731+00:00", "scope": "Scan 137 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("1۔ دفاعی ٹیم کا کوئی کھلاڑی 25 گز لائن کے اندر کوئی خطرناک فاؤل کرے۔","1. A player of the defending team commits a dangerous foul within the 25-yard line.","۱. د دفاعي ټیم کوم لوبغاړی د ۲۵ ګز لاین دننه کوم خطرناک فاول وکړي.",{"id": "hpe11-s137-p1", "listGroup": "pc"}),
hpe11Pair("2۔ دفاعی ٹیم کے کسی کھلاڑی کے پاؤں پر بال شوٹنگ سرکل کے اندر لگے۔","2. The ball hits the foot of a player of the defending team inside the shooting circle.","۲. د دفاعي ټیم د کوم لوبغاړي په پښه توپ د شوټنګ سرکل دننه ولګېږي.",{"id": "hpe11-s137-p2", "listGroup": "pc"}),
hpe11Pair("3۔ دفاعی ٹیم اگر دانستہ طور پر شوٹنگ سرکل کے اندر سے بال گول لائن سے باہر پھینک دے۔","3. The defending team deliberately throws the ball out over the goal line from inside the shooting circle.","۳. دفاعي ټیم که قصدي توګه د شوټنګ سرکل له دننه نه توپ له ګول لاین بهر وغورځوي.",{"id": "hpe11-s137-p3", "listGroup": "pc"}),
hpe11Pair("4۔ جب دفاعی ٹیم کے کھلاڑی ڈی سے بال خطرناک طریقے پر کلیئر کریں۔","4. When the players of the defending team clear the ball from the D in a dangerous manner.","۴. کله چې د دفاعي ټیم لوبغاړي له ډي نه توپ په خطرناکه طریقه کلیر کړي.",{"id": "hpe11-s137-p4", "listGroup": "pc"}),
hpe11Pair("5۔ فری ہٹ ملنے پر جان بوجھ کر ڈی کے قریب ہٹ لگانے میں تاخیر کرے۔ پنلٹی کارنر کے وقت حملہ آور ٹیم کے کھلاڑی سرکل کے باہر کھڑے ہوں گے اور ایک کھلاڑی بال پھینکنے کے لیے پنلٹی کارنر کے نشان پر کھڑا ہوگا۔","5. On getting a free hit, deliberately delays taking the hit near the D. At the time of the penalty corner the players of the attacking team will stand outside the circle and one player will stand at the penalty-corner mark to push the ball.","۵. د فري هټ په ترلاسه کولو سره قصدي توګه د ډي نږدې په هټ وهلو کې ځنډ وکړي. د پنلټي کارنر پر مهال به د برید کوونکي ټیم لوبغاړي د سرکل بهر ولاړ وي او یو لوبغاړی به د توپ غورځولو لپاره د پنلټي کارنر په نښه ولاړ وي.",{"id": "hpe11-s137-p5", "listGroup": "pc"}),
hpe11Pair("6۔ پنلٹی کارنر کے وقت دفاعی ٹیم کے پانچ کھلاڑی گول لائن پر ہوں گے اور باقی تمام کھلاڑی سنٹر لائن پر ہوں گے۔","6. At the time of the penalty corner five players of the defending team will be on the goal line and all the remaining players will be on the centre line.","۶. د پنلټي کارنر پر مهال به د دفاعي ټیم پنځه لوبغاړي په ګول لاین او پاتې ټول لوبغاړي به په سنټر لاین وي.",{"id": "hpe11-s137-p6", "listGroup": "pc"}),
hpe11Pair("7۔ پنلٹی کارنر کی ہٹ لگنے سے پہلے کوئی کھلاڑی بھاگ نہیں سکتا۔","7. No player can run before the penalty corner hit is made.","۷. د پنلټي کارنر د هټ له وهلو مخکې هېڅ لوبغاړی نشي منډې وهلی.",{"id": "hpe11-s137-p7", "listGroup": "pc"}),
hpe11Pair("8۔ پنلٹی کارنر سے بال اگر براہ راست گول میں جائے اور نیٹ میں لگے تو گول نہیں ہوگا اور اگر تختہ پر لگے تو گول دیا جائے گا۔ یہ قانون گاہے بگاہے بدلتا رہتا ہے۔ آج کل نیٹ پر لگنے سے بھی گول ہو جاتا ہے۔ ان ڈائریکٹ ہٹ کا بال اگر گول میں جائے تو گول دیا جائے گا بشرطیکہ کوئی فاؤل سرزد نہ ہوا ہو اور بال نے مکمل طور پر گول لائن عبور کر لی ہو۔ ڈائریکٹ ہٹ اگر کسی دفاعی کھلاڑی کی ہاکی سے لگ جائے تو تختہ کی قید نہیں ہوتی۔","8. If the ball from the penalty corner goes directly into the goal and hits the net it will not be a goal, and if it hits the board a goal will be given. This rule keeps changing from time to time. Nowadays a goal is scored even on hitting the net. If the ball from an indirect hit goes into the goal, a goal will be given provided no foul has been committed and the ball has crossed the goal line completely. If a direct hit touches the hockey stick of a defending player, the board restriction does not apply.","۸. د پنلټي کارنر نه که توپ مستقیم ګول ته ولاړ شي او جال ته ولګېږي نو ګول نه وي او که تختې ته ولګېږي نو ګول ورکول کېږي. دا قانون وخت په وخت بدلېږي. نن ورځ جال ته په لګېدو هم ګول کېږي. که د نامستقیم هټ توپ ګول ته ولاړ شي نو ګول ورکول کېږي په دې شرط چې کوم فاول نه وي شوی او توپ په بشپړ ډول د ګول لاین تېر کړی وي. که مستقیم هټ د دفاعي لوبغاړي له هاکۍ سره ولګېږي نو د تختې قید نه وي.",{"id": "hpe11-s137-p8", "listGroup": "pc"})
]});
