hpe11AddSection("hpe11-u07",{"id": "hpe11-s138-hockey-6", "title": "Hockey: penalty (punishment); penalty stroke", "headingUrdu": "ہاکی: سزا؛ پنلٹی سٹروک", "headingPashto": "هاکي: سزا؛ پنلټي سټروک", "sourceLanguage": "ur", "source": {"pdfPage": 138, "printedPage": "136"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s138-h1", "hpe11-s138-p2", "hpe11-s138-p3", "hpe11-s138-h4", "hpe11-s138-p5", "hpe11-s138-p6", "hpe11-s138-p7", "hpe11-s138-p8", "hpe11-s138-p9", "hpe11-s138-p10", "hpe11-s138-p11"]}, {"type": "figure", "index": 0}], "equations": [], "figures": [{"id": "hpe11-s138-fig1", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 260\" role=\"img\" aria-label=\"A penalty stroke being taken: a player at the left about to strike the ball, a goalkeeper in dark kit in the goal at the right, and two officials standing beside the goal\" style=\"width:100%;max-width:420px;height:auto;background:#fff\"><rect width=\"420\" height=\"260\" fill=\"#2e9e83\"/><rect width=\"420\" height=\"40\" fill=\"#5c6bc0\"/><polygon points=\"270,40 420,40 420,260 330,260\" fill=\"#e5a46a\"/><rect x=\"340\" y=\"120\" width=\"60\" height=\"90\" fill=\"none\" stroke=\"#eceff1\" stroke-width=\"4\"/><circle cx=\"345\" cy=\"150\" r=\"10\" fill=\"#212121\"/><rect x=\"335\" y=\"160\" width=\"22\" height=\"50\" rx=\"7\" fill=\"#212121\"/><circle cx=\"300\" cy=\"90\" r=\"8\" fill=\"#fdd835\"/><rect x=\"292\" y=\"98\" width=\"16\" height=\"40\" rx=\"5\" fill=\"#fdd835\"/><circle cx=\"90\" cy=\"150\" r=\"10\" fill=\"#f5cba7\"/><rect x=\"80\" y=\"160\" width=\"20\" height=\"45\" rx=\"7\" fill=\"#e53935\"/><line x1=\"70\" y1=\"200\" x2=\"55\" y2=\"225\" stroke=\"#222\" stroke-width=\"4\"/><circle cx=\"150\" cy=\"215\" r=\"5\" fill=\"#fff\"/></svg>", "caption": "A penalty stroke being taken with the goalkeeper in the goal", "captionUrdu": "پنلٹی سٹروک لگاتے ہوئے، گول میں گول کیپر", "captionPashto": "پنلټي سټروک وهلو سره، په ګول کې ګول کیپر", "labels": [], "sourceGap": {"note": "The original is a coloured photograph; replaced by a simplified coded SVG schematic (no raster image)."}}], "sourceNote": "Printed page 136: penalty (punishment) cases A–B, penalty stroke cases A–F, with a photograph of a penalty stroke at the foot. The page number “136” is shown in a hexagon at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T03:04:10.661738+00:00", "scope": "Scan 138 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("سزا","Penalty (Punishment)","سزا",{"id": "hpe11-s138-h1", "kind": "heading"}),
hpe11Pair("ا۔ اگر دفاعی ٹیم بار بار قانون شکنی کرے تو امپائر پنلٹی سٹروک دے سکتا ہے۔","A. If the defending team breaks the rules repeatedly, the umpire can award a penalty stroke.","ا. که دفاعي ټیم په پرله پسې ډول قانون ماتوي نو امپایر پنلټي سټروک ورکولی شي.",{"id": "hpe11-s138-p2", "listGroup": "pu"}),
hpe11Pair("ب۔ اگر حملہ آور ٹیم خلاف ورزی کرے تو دفاعی ٹیم کو فری ہٹ دی جائے گی۔","B. If the attacking team commits a violation, a free hit will be given to the defending team.","ب. که برید کوونکی ټیم سرغړونه وکړي نو دفاعي ټیم ته فري هټ ورکول کېږي.",{"id": "hpe11-s138-p3", "listGroup": "pu"}),
hpe11Pair("پنلٹی سٹروک","Penalty Stroke","پنلټي سټروک",{"id": "hpe11-s138-h4", "kind": "heading"}),
hpe11Pair("پنلٹی سٹروک درج ذیل صورتوں میں دیا جاتا ہے۔","A penalty stroke is given in the following cases.","پنلټي سټروک په لاندې صورتونو کې ورکول کېږي.",{"id": "hpe11-s138-p5"}),
hpe11Pair("ا۔ جب پنلٹی کارنر کے وقت دفاعی ٹیم بار بار قانون شکنی کرے۔","A. When the defending team repeatedly breaks the rules at the time of a penalty corner.","ا. کله چې د پنلټي کارنر پر مهال دفاعي ټیم په پرله پسې ډول قانون ماتوي.",{"id": "hpe11-s138-p6", "listGroup": "ps"}),
hpe11Pair("ب۔ گول لائن کے اوپر گول پوسٹوں کے درمیان دفاعی ٹیم کے کھلاڑی کے پاؤں پر لگے۔","B. The ball hits the foot of a player of the defending team on the goal line between the goal posts.","ب. د ګول لاین پر سر د ګول پوسټونو ترمنځ د دفاعي ټیم د لوبغاړي په پښه ولګېږي.",{"id": "hpe11-s138-p7", "listGroup": "ps"}),
hpe11Pair("ج۔ بال اگر گول کیپر پکڑے یا دھکیلے۔","C. If the goalkeeper catches or pushes the ball.","ج. که ګول کیپر توپ ونیسي یا وټیلي.",{"id": "hpe11-s138-p8", "listGroup": "ps"}),
hpe11Pair("د۔ جب دفاعی ٹیم کا کوئی کھلاڑی حملہ آور ٹیم کے کھلاڑی کو اس وقت خطرناک طریقے سے روکے جب وہ گول کرنے کی پوزیشن میں ہو۔","D. When a player of the defending team stops a player of the attacking team in a dangerous manner while he is in a position to score a goal.","د. کله چې د دفاعي ټیم کوم لوبغاړی د برید کوونکي ټیم لوبغاړی په خطرناکه طریقه هغه مهال ودروي چې هغه د ګول کولو په موقعیت کې وي.",{"id": "hpe11-s138-p9", "listGroup": "ps"}),
hpe11Pair("ہ۔ پنلٹی سٹروک کے وقت دونوں ٹیموں کے کھلاڑی 25 گز کے فاصلے پر ہوں گے جبکہ حملہ آور ٹیم کا ایک کھلاڑی پنلٹی سٹروک کی جگہ پر ہوگا اور دفاعی ٹیم کا گول کیپر گول میں ہوگا۔","E. At the time of the penalty stroke the players of both teams will be at a distance of 25 yards, while one player of the attacking team will be at the penalty-stroke spot and the goalkeeper of the defending team will be in the goal.","ه. د پنلټي سټروک پر مهال به د دواړو ټیمونو لوبغاړي د ۲۵ ګزو په واټن وي پداسې حال کې چې د برید کوونکي ټیم یو لوبغاړی به د پنلټي سټروک په ځای او د دفاعي ټیم ګول کیپر به په ګول کې وي.",{"id": "hpe11-s138-p10", "listGroup": "ps"}),
hpe11Pair("و۔ پنلٹی سٹروک سے بال اگر گول میں گول لائن عبور کر کے چلا جائے تو گول دیا جائے گا اور اگر گول کیپر بال کو روک لے یا بال پوسٹوں سے لگ کر واپس آ جائے تو پنلٹی سٹروک ضائع ہوگا۔","F. If the ball from the penalty stroke crosses the goal line into the goal, a goal will be given, and if the goalkeeper stops the ball or the ball rebounds from the posts, the penalty stroke is lost.","و. که د پنلټي سټروک نه توپ د ګول لاین تېرولو سره ګول ته ولاړ شي نو ګول ورکول کېږي او که ګول کیپر توپ ودروي یا توپ له پوسټونو سره لګېدو سره بېرته راشي نو پنلټي سټروک ضایع کېږي.",{"id": "hpe11-s138-p11", "listGroup": "ps"})
]});
