hpe11AddSection("hpe11-u07",{"id": "hpe11-s139-hockey-7", "title": "Hockey: when a goal is scored; hit-in; other violations; punishment", "headingUrdu": "ہاکی: گول کب ہوتا ہے؛ ہٹ ان؛ دیگر خلاف ورزیاں؛ سزا", "headingPashto": "هاکي: ګول کله کېږي؛ هټ ان؛ نورې سرغړونې؛ سزا", "sourceLanguage": "ur", "source": {"pdfPage": 139, "printedPage": "137"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s139-h1", "hpe11-s139-p2", "hpe11-s139-h3", "hpe11-s139-p4", "hpe11-s139-h5", "hpe11-s139-p6", "hpe11-s139-p7", "hpe11-s139-p8", "hpe11-s139-p9", "hpe11-s139-p10", "hpe11-s139-p11", "hpe11-s139-h12", "hpe11-s139-p13"]}], "equations": [], "sourceNote": "Printed page 137: when a goal is scored, hit-in, other violations (1–6) and the penalty for them. The page number “137” is shown in a hexagon at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T03:04:11.205649+00:00", "scope": "Scan 139 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("گول کب ہوتا ہے","When a Goal Is Scored","ګول کله کېږي",{"id": "hpe11-s139-h1", "kind": "heading"}),
hpe11Pair("جب حملہ آور ٹیم کا کوئی کھلاڑی شوٹنگ سرکل کے اندر سے بال کو ہٹ کرے اور بال گول پوسٹوں کے درمیان سے اور کراس بار کے نیچے سے مکمل طور پر گول لائن عبور کرے اور اس دوران کوئی فاؤل سرزد نہ ہوا ہو تو گول دیا جائے گا۔","When a player of the attacking team hits the ball from inside the shooting circle and the ball crosses the goal line completely between the goal posts and under the crossbar, and no foul has been committed during that time, a goal will be given.","کله چې د برید کوونکي ټیم کوم لوبغاړی د شوټنګ سرکل له دننه نه توپ هټ کړي او توپ د ګول پوسټونو ترمنځ او د کراس بار لاندې په بشپړ ډول د ګول لاین تېر کړي او په دې موده کې کوم فاول نه وي شوی نو ګول ورکول کېږي.",{"id": "hpe11-s139-p2"}),
hpe11Pair("ہٹ ان","Hit-in","هټ ان",{"id": "hpe11-s139-h3", "kind": "heading"}),
hpe11Pair("جب بال مکمل طور پر سائیڈ لائن عبور کر جائے تو ہٹ ان دی جاتی ہے۔ جس کھلاڑی سے آخری مرتبہ بال ٹچ ہو کر سائیڈ لائن عبور کرے اس کی مخالف ٹیم کو ہٹ ان دی جائے گی۔ ہٹ ان کے وقت کھلاڑی 5 گز کے فاصلے پر ہوں گے۔ ہٹ ان کرنے والا کھلاڑی بال کو دوبارہ اس وقت تک نہیں کھیل سکتا جب تک دوسرا کھلاڑی اسے ٹچ نہ کرے۔","When the ball crosses the sideline completely, a hit-in is given. The opposing team of the player by whom the ball was last touched before crossing the sideline will be given the hit-in. At the time of the hit-in the players will be at a distance of 5 yards. The player taking the hit-in cannot play the ball again until another player touches it.","کله چې توپ په بشپړ ډول د اړخ لاین تېر کړي نو هټ ان ورکول کېږي. د هغه لوبغاړي مخالف ټیم ته چې له هغه نه وروستی ځل توپ لمس شوی او د اړخ لاین یې تېر کړی هټ ان ورکول کېږي. د هټ ان پر مهال به لوبغاړي د ۵ ګزو په واټن وي. هټ ان کوونکی لوبغاړی بیا توپ نشي لوبولی تر هغه چې بل لوبغاړی هغه ونه لمسوي.",{"id": "hpe11-s139-p4"}),
hpe11Pair("دیگر خلاف ورزیاں","Other Violations","نورې سرغړونې",{"id": "hpe11-s139-h5", "kind": "heading"}),
hpe11Pair("1۔ کھیل کے دوران پاؤں یا جسم کے کسی حصہ سے بال چھو جانا۔","1. The ball touching the foot or any part of the body during the game.","۱. د لوبې په موده کې توپ ته په پښه یا د بدن کوم برخه لګېدل.",{"id": "hpe11-s139-p6", "listGroup": "ov"}),
hpe11Pair("2۔ کھیل میں کسی قسم کی رکاوٹ پیدا کرنا۔","2. Creating any kind of obstruction in the game.","۲. په لوبه کې هر ډول خنډ جوړول.",{"id": "hpe11-s139-p7", "listGroup": "ov"}),
hpe11Pair("3۔ وقت ضائع کرنے کی کوشش کرنا۔","3. Trying to waste time.","۳. د وخت ضایع کولو هڅه کول.",{"id": "hpe11-s139-p8", "listGroup": "ov"}),
hpe11Pair("4۔ خطرناک طریقے سے بال کو مخالف کی طرف ہٹ کرنا۔","4. Hitting the ball towards the opponent in a dangerous manner.","۴. په خطرناکه طریقه توپ مخالف لوري ته هټ کول.",{"id": "hpe11-s139-p9", "listGroup": "ov"}),
hpe11Pair("5۔ الٹی ہاکی سے بال کو روکنا یا ہٹ کرنا۔","5. Stopping or hitting the ball with the reverse side of the stick.","۵. په الټه هاکۍ توپ درول یا هټ کول.",{"id": "hpe11-s139-p10", "listGroup": "ov"}),
hpe11Pair("6۔ ناشائستہ رویہ اختیار کرنا۔","6. Adopting improper conduct.","۶. ناوړه چلند خپلول.",{"id": "hpe11-s139-p11", "listGroup": "ov"}),
hpe11Pair("سزا","Penalty","سزا",{"id": "hpe11-s139-h12", "kind": "heading"}),
hpe11Pair("کھیل کے دوران اگر درج بالا بے ضابطگی ہو تو فری ہٹ دی جاتی ہے اور اگر شوٹنگ سرکل کے اندر ہو تو پنلٹی کارنر یا سٹروک دیا جا سکتا ہے۔ ناشائستہ رویہ پر کسی کھلاڑی کو عارضی یا مستقل طور پر باہر نکالا جا سکتا ہے۔","If the above irregularity occurs during the game a free hit is given, and if it is inside the shooting circle a penalty corner or stroke can be given. For improper conduct a player can be sent off temporarily or permanently.","که د لوبې په موده کې پورتنۍ بې ضابطګي وشي نو فري هټ ورکول کېږي او که د شوټنګ سرکل دننه وي نو پنلټي کارنر یا سټروک ورکول کېدای شي. په ناوړه چلند کوم لوبغاړی لنډمهاله یا تلپاتې توګه بهر ایستل کېدای شي.",{"id": "hpe11-s139-p13"})
]});
