hpe11AddSection("hpe11-back-matter",{"id": "hpe11-s146-authors-1", "title": "Introduction of the authors (1): Malik Asif, Arif Ali Shah, Samiullah Marwat", "headingUrdu": "مصنفین کا تعارف (1): ملک آصف، عارف علی شاہ، سمیع اللہ مروت", "headingPashto": "د لیکوالانو پېژندنه (۱): ملک آصف، عارف علي شاه، سمیع الله مروت", "sourceLanguage": "ur", "source": {"pdfPage": 146, "printedPage": "144"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["hpe11-s146-h1", "hpe11-s146-h2", "hpe11-s146-p3", "hpe11-s146-h4", "hpe11-s146-p5", "hpe11-s146-h6", "hpe11-s146-p7"]}], "equations": [], "sourceNote": "Printed page 144: heading Introduction of the Authors (مصنفین کا تعارف) with Malik Asif, Arif Ali Shah and Samiullah Marwat. Printed “Gomal”, “DPE” and “DCTE” kept as in the source. The page number “144” is shown in a hexagon at the foot. English and Pashto are our translations (need native review); watermark and footer strip excluded.", "review": {"reviewedAtUtc": "2026-10-13T03:06:33.175123+00:00", "scope": "Scan 146 compared with source", "unresolved": "Translations need native review"}, "paras": [
hpe11Pair("مصنفین کا تعارف","Introduction of the Authors","د لیکوالانو پېژندنه",{"id": "hpe11-s146-h1", "kind": "heading"}),
hpe11Pair("ملک آصف:","Malik Asif:","ملک آصف:",{"id": "hpe11-s146-h2", "kind": "heading"}),
hpe11Pair("ملک آصف نے 1983 میں گومل یونیورسٹی سے صحت و جسمانی تعلیم (HPE) میں ایم ایس سی کی ڈگری حاصل کی اور درس و تدریس کے شعبے سے وابستہ ہو گئے۔ آپ نے مختلف کالجوں میں بطور DPE خدمات سرانجام دیے اور 2015 میں گورنمنٹ پوسٹ گریجویٹ کالج نمبر 1، ایبٹ آباد سے بطور پروفیسر HPE ریٹائرڈ ہوئے۔ آپ کئی کتابوں کے مصنف بھی ہیں۔","Malik Asif received an M.Sc. degree in Health and Physical Education (HPE) from Gomal University in 1983 and joined the field of teaching. He served as DPE in various colleges and retired in 2015 as Professor of HPE from Government Postgraduate College No. 1, Abbottabad. He is also the author of several books.","ملک آصف په ۱۹۸۳ کې د ګومل پوهنتون نه په روغتیا او فزیکي زده کړه (HPE) کې د ایم ایس سي سند ترلاسه کړ او د تدریس په څانګه پورې تړلی شو. هغه په بېلابېلو کالجونو کې د DPE په توګه خدمتونه ترسره کړل او په ۲۰۱۵ کې له ګورنمنټ پوسټ ګریجویټ کالج نمبر ۱، ایبټ آباد نه د HPE د پروفیسر په توګه تقاعد شو. هغه د ډېرو کتابونو لیکوال هم دی.",{"id": "hpe11-s146-p3"}),
hpe11Pair("عارف علی شاہ:","Arif Ali Shah:","عارف علي شاه:",{"id": "hpe11-s146-h4", "kind": "heading"}),
hpe11Pair("عارف علی شاہ نے 2003 میں یونیورسٹی آف کراچی سے صحت و جسمانی تعلیم (HPE) میں ایم ایس سی کی ڈگری حاصل کی اور گولڈ میڈل حاصل کیا۔ آپ 2006 سے درس و تدریس کے شعبے سے وابستہ ہے۔ آج کل گورنمنٹ پوسٹ گریجویٹ کالج نمبر 1، ایبٹ آباد میں بطور چیئرمین HPE ڈیپارٹمنٹ کے خدمات سرانجام دے رہے ہیں۔","Arif Ali Shah received an M.Sc. degree in Health and Physical Education (HPE) from the University of Karachi in 2003 and won a gold medal. He has been associated with teaching since 2006. At present he is serving as Chairman of the HPE Department at Government Postgraduate College No. 1, Abbottabad.","عارف علي شاه په ۲۰۰۳ کې د کراچۍ پوهنتون نه په روغتیا او فزیکي زده کړه (HPE) کې د ایم ایس سي سند ترلاسه کړ او د سرو زرو مډال یې وګاټه. هغه له ۲۰۰۶ راهیسې د تدریس په څانګه پورې تړلی دی. اوس مهال په ګورنمنټ پوسټ ګریجویټ کالج نمبر ۱، ایبټ آباد کې د HPE ډیپارټمنټ د چیرمین په توګه خدمتونه ترسره کوي.",{"id": "hpe11-s146-p5"}),
hpe11Pair("سمیع اللہ مروت:","Samiullah Marwat:","سمیع الله مروت:",{"id": "hpe11-s146-h6", "kind": "heading"}),
hpe11Pair("سمیع اللہ مروت نے 1996 میں گومل یونیورسٹی سے صحت و جسمانی تعلیم (HPE) میں ایم ایس سی کی ڈگری حاصل کی۔ مختلف سکولوں میں بطور DPE کے خدمات سرانجام دیے ہیں۔ آج کل DCTE ایبٹ آباد میں بطور ڈائریکٹر فزیکل ایجوکیشن اینڈ سپورٹس کے خدمات سرانجام دے رہے ہیں۔","Samiullah Marwat received an M.Sc. degree in Health and Physical Education (HPE) from Gomal University in 1996. He has served as DPE in various schools. At present he is serving as Director of Physical Education and Sports at the DCTE, Abbottabad.","سمیع الله مروت په ۱۹۹۶ کې د ګومل پوهنتون نه په روغتیا او فزیکي زده کړه (HPE) کې د ایم ایس سي سند ترلاسه کړ. په بېلابېلو ښوونځیو کې یې د DPE په توګه خدمتونه ترسره کړي دي. اوس مهال په DCTE ایبټ آباد کې د فزیکل ایجوکیشن او سپورټس د ډایرکټر په توګه خدمتونه ترسره کوي.",{"id": "hpe11-s146-p7"})
]});
